-- Atmosphere/LowHealth.lua
L["How the low-health screen edges look."] = "L'aspetto dei bordi dello schermo con salute bassa."
L["Turns this page's look settings on or off."] = "Attiva o disattiva le impostazioni d'aspetto di questa pagina."
L["Shows your health falling in the preview and on screen."] = "Mostra la tua salute che cala nell'anteprima e sullo schermo."
L["The look of the edges; Auto picks one for your class and spec."] = "L'aspetto dei bordi; Auto ne sceglie uno per la tua classe e specializzazione."
L["Undoes your changes to this theme."] = "Annulla le tue modifiche a questo tema."
L["Gives you this theme as text to share."] = "Ti dà questo tema come testo da condividere."
L["Makes a blank theme of your own."] = "Crea un tuo tema vuoto."
L["Sound:"] = "Suono:"
L["The sound that plays as your health runs low."] = "Il suono che si sente quando la salute si abbassa."
L["Ambient volume"] = "Volume ambientale"
L["How loud the sound plays compared to your ambient volume."] = "Quanto è forte il suono rispetto al tuo volume ambientale."
L["How strong the whole effect is."] = "Quanto è intenso l'intero effetto."
L["How far in from the edges the whole effect comes."] = "Quanto entra l'intero effetto dai bordi."
L["How bright the art's colors are."] = "Quanto sono vivaci i colori della grafica."
L["Black at 0%, the theme's color at 100%."] = "Nero allo 0%, il colore del tema al 100%."
L["The edges flash when a big hit lands."] = "I bordi lampeggiano quando arriva un colpo forte."
L["Flash darkness"] = "Oscurità del lampo"
L["How much darker the edges get in a flash, on top of Darkness."] = "Quanto si scuriscono i bordi in un lampo, oltre a Oscurità."
L["Flash color"] = "Colore del lampo"
L["How much a flash tints the edges."] = "Quanto un lampo colora i bordi."
L["Flash fade"] = "Dissolvenza del lampo"
L["Seconds a flash takes to fade."] = "Secondi che un lampo impiega a svanire."
L["How far in it comes from the left and right sides."] = "Quanto entra dai lati sinistro e destro."
L["The sparks that float over the edges."] = "Le scintille che fluttuano sui bordi."
L["Wisps of heat rise from the bottom of the screen as you weaken."] = "Volute di calore salgono dal fondo dello schermo mentre ti indebolisci."
L["A swirl that turns over the screen as you weaken."] = "Un vortice che gira sullo schermo mentre ti indebolisci."
L["The kind of swirl."] = "Il tipo di vortice."
L["How fast the swirl turns; below 0 turns the other way."] = "Quanto velocemente gira il vortice; sotto 0 gira al contrario."
L["The game's own screen effects closing in at the edges."] = "Gli effetti schermo del gioco che si chiudono ai bordi."
L["A wave of the game's art creeps in on each heartbeat."] = "Un'onda della grafica del gioco avanza a ogni battito del cuore."
L["Which of the game's effects shows."] = "Quale effetto del gioco viene mostrato."
L["What shape cuts the effect to the screen's edges."] = "Quale forma ritaglia l'effetto ai bordi dello schermo."
L["Tint the effect to your theme or keep its own colors."] = "Colora l'effetto con il tuo tema o mantieni i suoi colori."
L["A second game effect over the first."] = "Un secondo effetto del gioco sopra il primo."
L["The game's effects slide slowly under their edge."] = "Gli effetti del gioco scorrono lentamente sotto il loro bordo."
L["One of the game's full-screen effects closing in as you weaken."] = "Uno degli effetti a schermo intero del gioco che si chiude mentre ti indebolisci."
L["Turns Vitals Vision on or off."] = "Attiva o disattiva Vitals Vision."
L["The screen's edges close in as your health drops."] = "I bordi dello schermo si chiudono man mano che la salute cala."
L["How strong the edges are out of a fight."] = "Quanto sono intensi i bordi fuori dal combattimento."
L["Ramp up"] = "Progressione"
L["Higher makes the edges close in slowly at first, then faster."] = "Più alto fa chiudere i bordi lentamente all'inizio, poi più in fretta."
L["Replace game's low health flash setting"] = "Sostituisci il lampo di salute bassa del gioco"
L["When the game's Do Not Flash Screen at Low Health setting is ticked, the edges don't show."] = "Quando l'opzione del gioco per non far lampeggiare lo schermo con salute bassa è spuntata, i bordi non appaiono."
L["Game setting: |cffff8000no flash|r (edges off while followed)"] = "Opzione del gioco: |cffff8000nessun lampo|r (bordi disattivati finché la segui)"
L["Game setting: |cff00ff00flash on|r"] = "Opzione del gioco: |cff00ff00lampo attivo|r"
L["How fast the edges close in when your health drops."] = "Quanto velocemente si chiudono i bordi quando la salute cala."
L["How fast the edges lift when you're healed."] = "Quanto velocemente si ritirano i bordi quando vieni curato."
L["Smaller hits that add up to this much of your health count as a big one."] = "Colpi più piccoli che sommati arrivano a questa parte della tua salute contano come uno forte."

-- Atmosphere/TeleportVision.lua
L["Teleport Vision"] = "Teleport Vision"
