L["The portal's color: your class and spec's, any class's, or your own."] = "Il colore del portale: quello della tua classe e specializzazione, di qualsiasi classe, o uno tuo."
L["Clouds in its color swirl outside the rim, filling the screen."] = "Nuvole del suo colore turbinano fuori dal bordo, riempiendo lo schermo."
L["Black edges close in from the sides as the cast fills."] = "Bordi neri si chiudono dai lati man mano che il lancio si riempie."
L["How long before the cast ends the screen goes fully black; 0 turns it off."] = "Quanto prima della fine del lancio lo schermo diventa del tutto nero; 0 lo disattiva."
