L["Puts this page's settings back to your profile's values."] = "Riporta le impostazioni di questa pagina ai valori del tuo profilo."
L["page"] = "pagina"
L["Click it for quick options and a link to these settings, drag to move it."] = "Cliccalo per le opzioni rapide e un collegamento a queste impostazioni, trascinalo per spostarlo."
L["Show in addon compartment"] = "Mostra nello scomparto AddOn"
L["Lists Cinematic in the game's addon list by the minimap."] = "Elenca Cinematic nell'elenco degli AddOn del gioco vicino alla minimappa."
L["The minimap button glows while a vision is doing something."] = "Il pulsante della minimappa si illumina mentre una Vision sta facendo qualcosa."
L["Suggest /cine commands while typing"] = "Suggerisci i comandi /cine mentre scrivi"
L["Typing /cine in chat lists the commands that fit."] = "Scrivere /cine in chat elenca i comandi corrispondenti."
L["The language Cinematic's text is in; a change needs a reload."] = "La lingua dei testi di Cinematic; una modifica richiede di ricaricare."
L["The look of Cinematic's settings windows: HD is flat and dark, and SD looks like the game's own."] = "L'aspetto delle finestre delle impostazioni di Cinematic: HD è piatto e scuro, SD somiglia a quello del gioco."
L["The game's %s is off"] = "%s del gioco è disattivato"
L["Couldn't turn it on right now; try again after the fight."] = "Impossibile attivarlo ora; riprova dopo il combattimento."
L["On. Right-click to turn all its tabs off."] = "Attivato. Clic destro per disattivare tutte le sue schede."
L["Off. Right-click to turn all its tabs on."] = "Disattivato. Clic destro per attivare tutte le sue schede."
L["Cinematic is about bringing Azeroth to life: your screen changes with the moment you're in, hiding what you don't need and showing what you do."] = "Cinematic serve a dare vita ad Azeroth: lo schermo cambia con il momento che vivi, nascondendo ciò che non ti serve e mostrando ciò che ti serve."
L["Reset Settings keeps what you made, Reset EVERYTHING deletes it all, and both reload the UI."] = "Ripristina impostazioni mantiene ciò che hai creato, Ripristina TUTTO elimina tutto, ed entrambi ricaricano l'interfaccia."
L["Effects that play over the world when something happens."] = "Effetti che appaiono sul mondo quando succede qualcosa."
L["How the whole interface looks."] = "L'aspetto dell'intera interfaccia."
L["Atmosphere"] = "Atmosfera"
L["The camera coming alive."] = "La telecamera che prende vita."
L["How fast the UI fades, the Calm Timer, and what takes you out of CineMode."] = "Quanto velocemente si dissolve l'interfaccia, il Timer di calma, e cosa ti fa uscire da CineMode."
L["Your interface fades away but comes back when you need it to."] = "La tua interfaccia si dissolve ma torna quando ti serve."
L["Nothing fades right now."] = "Niente si dissolve in questo momento."
L["Click to turn CineMode off."] = "Clic per disattivare CineMode."
L["Click to turn CineMode on."] = "Clic per attivare CineMode."
L["Click to see why."] = "Clic per vedere perché."
L["CineMode is on"] = "CineMode è attivo"
L["CineMode is off"] = "CineMode è disattivato"
L["Cameras (Camera tab) is set to CineMode."] = "Telecamere (scheda Telecamera) è impostato su CineMode."
L["This page does nothing."] = "Questa pagina non fa nulla."
L["Works while CineMode is on, and outside it while friendly nameplates show."] = "Funziona mentre CineMode è attivo, e fuori da esso mentre le barre dei nomi amiche sono visibili."
L["Works only while CineMode is on."] = "Funziona solo mentre CineMode è attivo."
L["Works while CineMode is off too."] = "Funziona anche mentre CineMode è disattivato."
L["This page works as its settings say."] = "Questa pagina funziona come dicono le sue impostazioni."
L["Click to turn it on or off."] = "Clic per attivarlo o disattivarlo."
L["off with %s"] = "disattivato con %s"
L["How fast the UI fades and what brings it back while CineMode is on."] = "Quanto velocemente si dissolve l'interfaccia e cosa la fa tornare mentre CineMode è attivo."
L["How fast the UI fades, the Calm Timer, and fights coming in."] = "Quanto velocemente si dissolve l'interfaccia, il Timer di calma, e l'inizio dei combattimenti."
L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "Cosa ti fa uscire da CineMode: combattimenti, luoghi, gruppi, movimento e finestre."
L["The minimap button, /cine hints, language and the menus' look."] = "Il pulsante della minimappa, i suggerimenti di /cine, la lingua e l'aspetto dei menu."
L["How long things take to fade in out of combat."] = "Quanto ci mettono le cose a comparire fuori dal combattimento."
L["How long things take to fade out."] = "Quanto ci mettono le cose a dissolversi."
L["How long things take to fade in during a fight."] = "Quanto ci mettono le cose a comparire durante un combattimento."
L["Casts count too when a rule uses Casting."] = "Anche i lanci contano quando una regola usa Casting."
L["As soon as a fight ends"] = "Appena finisce un combattimento"
L["How long after a fight before CineMode comes back."] = "Quanto tempo dopo un combattimento torna CineMode."
L["Ends the Calm Timer early once your health and power are back to full."] = "Termina prima il Timer di calma quando salute e potere tornano al massimo."
L["With a pet out, its health must be full too."] = "Con un famiglio evocato, anche la sua salute deve essere al massimo."
L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "Esce da CineMode mentre è aperta la finestra di un PNG, come un PNG delle missioni o un mercante."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "Esce da CineMode mentre è aperta una finestra del gioco, come le borse o la mappa."
L["Picking up an item or spell brings the UI back until you put it down."] = "Prendere un oggetto o un incantesimo col cursore fa tornare l'interfaccia finché non lo lasci."
L["How long things must stay calm before CineMode comes back."] = "Quanto deve restare tutto calmo prima che torni CineMode."
L["Casting at an enemy out of combat brings up your combat frames."] = "Lanciare su un nemico fuori dal combattimento fa comparire i tuoi riquadri da combattimento."
L["Being in combat brings the UI back."] = "Entrare in combattimento fa tornare l'interfaccia."
L["In the open world"] = "Nel mondo aperto"
L["Anywhere outside cities, dungeons and raids."] = "Ovunque fuori da città, spedizioni e incursioni."
L["Capital cities, including Dalaran."] = "Le capitali, Dalaran compresa."
L["While you're flagged for PvP out in the world."] = "Mentre hai il PvP attivo nel mondo."
L["In battlegrounds"] = "Nei campi di battaglia"
L["Battlegrounds and arenas."] = "Campi di battaglia e arene."
L["Back after stopping"] = "Ritorno dopo la sosta"
L["CineMode comes back once you've stood still this long."] = "CineMode torna quando sei rimasto fermo per questo tempo."
L["Back after moving"] = "Ritorno dopo il movimento"
L["CineMode comes back once you've kept moving this long."] = "CineMode torna quando hai continuato a muoverti per questo tempo."
L["Allow outside CineMode"] = "Consenti fuori da CineMode"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "CineMode nasconde i tuoi effetti benefici e penalizzanti: scegli cosa li fa tornare."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "Ottenere o rinnovare un effetto benefico mostra per poco i tuoi effetti benefici e penalizzanti."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "Permette a questa pagina di far tornare in CineMode i tuoi effetti benefici e penalizzanti nascosti."
L["What brings your hidden buffs and debuffs up for a while."] = "Cosa fa comparire per un po' i tuoi effetti benefici e penalizzanti nascosti."
L["Buffs you or your pet cast on yourself don't bring them up."] = "Gli effetti benefici che tu o il tuo famiglio lanciate su di te non li fanno comparire."
L["Not while skyriding"] = "Non durante il volo dinamico"
L["No buff brings them up while you're on a skyriding mount."] = "Nessun effetto benefico li fa comparire mentre sei su una cavalcatura da volo dinamico."
L["Only the buff you gained or refreshed shows."] = "Si vede solo l'effetto benefico ottenuto o rinnovato."
L["Keep ones lasting less than up until they run out"] = "Mostra finché durano quelli più brevi di"
L["A short buff stays up for as long as it lasts."] = "Un effetto benefico breve resta visibile per tutta la sua durata."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "Ottenere o rinnovare un effetto penalizzante mostra per poco i tuoi effetti penalizzanti."
L["Only within the Calm Timer after a fight."] = "Solo durante il Timer di calma dopo un combattimento."
L["Keeps them up while you have any debuff."] = "Li tiene visibili finché hai un qualsiasi effetto penalizzante."
L["Debuffs that last longer than this don't bring them up."] = "Gli effetti penalizzanti che durano più di così non li fanno comparire."
L["Override Default Buff Reveal Time"] = "Cambia la durata predefinita per gli effetti benefici"
L["How long a new buff keeps the buffs up."] = "Per quanto un nuovo effetto benefico tiene visibili gli effetti."
L["Override Default Debuff Reveal Time"] = "Cambia la durata predefinita per gli effetti penalizzanti"
L["How long a new debuff keeps the buffs up."] = "Per quanto un nuovo effetto penalizzante tiene visibili gli effetti."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "Ottenere questo non fa comparire i tuoi effetti; scrivi un ID o nome di incantesimo."
L["Keeps drifting to new random distances after the first pull-back."] = "Continua a spostarsi a nuove distanze casuali dopo il primo allontanamento."
L["How much closer than your own zoom the random zoom may come."] = "Quanto più vicino del tuo zoom può arrivare lo zoom casuale."
L["How much of each zoom is spent speeding up and slowing down."] = "Quanta parte di ogni zoom è dedicata ad accelerare e rallentare."
L["Each pause varies at random by up to this much."] = "Ogni pausa varia a caso fino a questo valore."
L["Raises the game's max camera distance while pulled back."] = "Alza la distanza massima della telecamera del gioco mentre è allontanata."
L["Lets the cameras start as the rows below say."] = "Permette alle telecamere di partire come dicono le righe qui sotto."
L["Top speed in the middle of a sweep."] = "Velocità massima a metà di una panoramica."
L["Each new angle is at least this many degrees from the last."] = "Ogni nuovo angolo dista almeno questi gradi dal precedente."
L["How far the camera may sway to either side."] = "Quanto può oscillare la telecamera da un lato o dall'altro."
L["Each move also tilts the camera to a random angle between these limits."] = "Ogni movimento inclina anche la telecamera a un angolo casuale entro questi limiti."
L["The camera never tilts more than this far below where it started."] = "La telecamera non si inclina mai più di così sotto il punto di partenza."
L["How much of each move is spent speeding up and slowing down."] = "Quanta parte di ogni movimento è dedicata ad accelerare e rallentare."
L["How long the camera rests between sweeps."] = "Quanto si ferma la telecamera tra una panoramica e l'altra."
L["Puts this camera's settings back to your profile's values."] = "Riporta le impostazioni di questa telecamera ai valori del tuo profilo."
L["Runs this camera for 30 seconds where you stand."] = "Avvia questa telecamera per 30 secondi dove ti trovi."
L["The camera slowly pulls back, then drifts in and out."] = "La telecamera si allontana lentamente, poi si avvicina e si allontana."
L["After you move the camera yourself, it waits this long before carrying on."] = "Dopo che muovi tu la telecamera, aspetta questo tempo prima di continuare."
L["Doing the emote or pressing the sit key."] = "Fare l'emote o premere il tasto per sedersi."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Cliccare Siediti, Inginocchiati o Sdraiati sulla scheda del falò, o il suo pulsante del fuoco (Emote Vision)."
L["Doing the emote, until you move or jump."] = "Fare l'emote, finché non ti muovi o salti."
L["Right-clicking a seat to sit on it."] = "Fare clic destro su un sedile per sedersi."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "Sguainare l'arma con il tasto per riporla fuori dal combattimento."
L["Casting your Hearthstone."] = "Usare la Pietra del Ritorno."
L["Casting a teleport spell."] = "Lanciare un incantesimo di teletrasporto."
L["Logging out where the game counts down first."] = "Disconnettersi dove il gioco fa prima il conto alla rovescia."
L["Doing the emote while standing still."] = "Fare l'emote restando fermi."
L["Casting Fishing, until you move or jump."] = "Lanciare Pesca, finché non ti muovi o salti."
L["Being flagged AFK."] = "Essere segnalato AFK."
L["Standing still for the time below with nothing else going on."] = "Restare fermi per il tempo qui sotto senza che succeda altro."
L["Taking off on a flight path."] = "Partire su una rotta di volo."
L["Talking to a quest giver."] = "Parlare con un PNG delle missioni."
L["Talking to an NPC about a quest step."] = "Parlare con un PNG di una fase di missione."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "Sulle rotte di volo, la telecamera oscilla da un lato all'altro con qualche sorvolo."
L["Your target's frames fade until you pick a new target or land."] = "I riquadri del bersaglio si dissolvono finché non scegli un nuovo bersaglio o atterri."
L["Sway from side to side"] = "Oscilla da un lato all'altro"
L["The camera sways from side to side around where it started."] = "La telecamera oscilla da un lato all'altro attorno al punto di partenza."
L["Your character does /look as a fly-by starts, which players nearby see."] = "Il tuo personaggio fa /look all'inizio di un sorvolo, e i giocatori vicini lo vedono."
L["About one fly-by per this many seconds of flight."] = "Circa un sorvolo ogni questi secondi di volo."
L["Turn round"] = "Girata"
L["Turn back before landing"] = "Torna prima dell'atterraggio"
L["Before you land, the camera turns back to where it was at takeoff."] = "Prima che atterri, la telecamera torna dov'era al decollo."
L["Turned back by"] = "Tornata entro"
L["How long before landing the camera has settled."] = "Quanto prima dell'atterraggio la telecamera si è assestata."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Quando resti fermo un po' o vai AFK, la telecamera gira lentamente attorno al tuo personaggio."
L["The camera sweeps around your character, pausing between sweeps."] = "La telecamera ruota attorno al tuo personaggio, fermandosi tra una panoramica e l'altra."
L["While you auto-run, the camera follows along until you stop or steer."] = "Mentre corri in automatico, la telecamera ti segue finché non ti fermi o cambi direzione."
L["The camera eases out a little, then drifts in and out."] = "La telecamera si allontana un po', poi si avvicina e si allontana."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Quando riposi, ti siedi o balli, la telecamera si gira lentamente verso di te e si avvicina."
L["How far the camera comes down toward the ground as it turns."] = "Quanto scende la telecamera verso terra mentre gira."
L["The camera eases in close, then drifts a little in and out."] = "La telecamera si avvicina, poi si avvicina e si allontana un po'."
L["The close-up distance the cozy camera zooms in to."] = "La distanza del primo piano a cui si avvicina la telecamera accogliente."
L["How much lower the camera sways, to look out across the view."] = "Quanto più in basso oscilla la telecamera, per guardare il panorama."
L["The camera eases out a little, then drifts slowly in and out."] = "La telecamera si allontana un po', poi si avvicina e si allontana lentamente."
L["The camera sways a little from side to side."] = "La telecamera oscilla un po' da un lato all'altro."
L["How much lower the camera sways, to look out across the water."] = "Quanto più in basso oscilla la telecamera, per guardare l'acqua."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Quando muori, la telecamera gira lentamente attorno al tuo corpo finché non liberi lo spirito o vieni resuscitato."
L["If you die in a boss fight, the death camera waits for it to end."] = "Se muori in uno scontro con un boss, la telecamera di morte aspetta che finisca."
L["No death camera when you can come back yourself, like with a soulstone."] = "Niente telecamera di morte quando puoi tornare da solo, come con una pietra dell'anima."
L["Adds a button under the release popup to get your own view back."] = "Aggiunge un pulsante sotto la finestra per liberare lo spirito per riavere la tua visuale."
L["How far the camera pulls back while you're dead."] = "Quanto si allontana la telecamera mentre sei morto."
L["How far the camera rises to look down on your body."] = "Quanto sale la telecamera per guardare dall'alto il tuo corpo."
L["The groups ticked here stay up while the death camera hides your frames."] = "I gruppi spuntati qui restano visibili mentre la telecamera di morte nasconde i tuoi riquadri."
L["Music file IDs, separated by commas; one plays at random when you die."] = "ID dei file musicali, separati da virgole; uno parte a caso quando muori."
L["The camera turns toward NPCs as they talk near you."] = "La telecamera si gira verso i PNG quando parlano vicino a te."
L["The fastest the camera swings toward a new speaker."] = "La velocità massima con cui la telecamera si gira verso un nuovo interlocutore."
L["How far from the screen's center the speaker ends up."] = "Quanto lontano dal centro dello schermo finisce chi parla."
L["How far the camera drifts side to side once settled."] = "Quanto oscilla la telecamera da un lato all'altro una volta assestata."
L["The camera turns around to find speakers you can't see."] = "La telecamera si gira per trovare chi parla fuori dalla tua vista."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Scatta verso chi parla, aggiunge alte bande nere con sottotitoli e dissolve tutta l'interfaccia."
L["How fast the camera zooms back out once the talking is over."] = "Quanto velocemente la telecamera si riallontana quando la conversazione è finita."
L["The longest a zoom in or out can take."] = "La durata massima di uno zoom avanti o indietro."
L["How long no one must talk before the camera turns back."] = "Quanto tempo nessuno deve parlare prima che la telecamera torni indietro."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Quando parli con un PNG delle missioni, la telecamera si avvicina e lo guarda da dietro di te."
L["Also zooms in for NPCs with nothing to say about quests."] = "Si avvicina anche per i PNG che non hanno nulla da dire sulle missioni."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "La telecamera resta ferma quando un PNG delle missioni ha solo missioni giornaliere o settimanali."
L["How far the camera turns to one side to look past you."] = "Quanto si gira la telecamera di lato per guardare oltre te."
L["How long the turn to the side takes."] = "Quanto dura la rotazione di lato."
L["How fast the camera zooms back out once you walk away."] = "Quanto velocemente la telecamera si riallontana quando te ne vai."
L["How far the camera comes down toward eye level."] = "Quanto scende la telecamera verso l'altezza degli occhi."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Quando usi la Pietra del Ritorno o un teletrasporto, la telecamera ruota attorno a te avvicinandosi."
L["The distance the zoom ends at as the cast finishes."] = "La distanza a cui finisce lo zoom alla fine del lancio."
L["Canceling"] = "Annullamento"
L["If you cancel the cast, the camera turns back to where it was."] = "Se annulli il lancio, la telecamera torna dov'era."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Impostazioni extra per le telecamere non ancora nella pagina Script."
L["Mouse Turn"] = "Rotazione col mouse"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Rende fluida la rotazione col tasto destro del mouse limitandone e addolcendone la velocità."
L["Cap"] = "Limite"
L["Cap right-click turn speed"] = "Limita la rotazione col clic destro"
L["Right-click turning never goes faster than the speed below."] = "La rotazione col clic destro non supera mai la velocità qui sotto."
L["Top turn speed"] = "Velocità massima di rotazione"
L["The fastest you can turn."] = "La rotazione più veloce possibile."
L["Ease back over"] = "Ritorno graduale in"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Quanto ci mette la tua velocità di visuale del mouse a tornare dopo che rallenti."
L["Ramp up right-click turn speed"] = "Accelera la rotazione col clic destro"
L["Each right-click turn starts slow and builds up to your own speed."] = "Ogni rotazione col clic destro parte lenta e sale fino alla tua velocità."
L["Start at"] = "Parti da"
L["%d%% of your speed"] = "%d%% della tua velocità"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "Con che velocità parte una rotazione, come quota della tua velocità di visuale del mouse."
L["Up to full speed over"] = "Velocità piena in"
L["How long a turn takes to build up to full speed."] = "Quanto ci mette una rotazione ad arrivare alla velocità piena."
L["Slow looking up and down too"] = "Rallenta anche lo sguardo su e giù"
L["Looking up and down slows by the same share as turning."] = "Guardare su e giù rallenta della stessa quota della rotazione."
L["Turns the whole Atmosphere hub on or off at once."] = "Attiva o disattiva in un colpo l'intero gruppo Atmosfera."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "L'aspetto del mondo di gioco in CineMode: vignettatura, luce delle locande, meteo e profondità di campo."
L["Pick where and when each effect shows in CineMode."] = "Scegli dove e quando appare ogni effetto in CineMode."
L["Shows all the time in CineMode, fights included."] = "Visibile sempre in CineMode, combattimenti compresi."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "Pioggia, neve e tempeste di sabbia colorano la scena, di più col maltempo intenso."
L["Reduce view distance in bad weather"] = "Riduci la visuale col maltempo"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Riduce la distanza visiva durante pioggia, neve o tempeste di sabbia, di più quanto più sono intense."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "Le impostazioni grafiche del gioco una per una, condivise da tutti i profili su questo computer."
L["Uses the settings below, or the game's own when turned off."] = "Usa le impostazioni qui sotto, o quelle del gioco se disattivato."
L["World"] = "Mondo"
L["Ground clutter, view distance, detail and shadows."] = "Vegetazione, distanza visiva, dettaglio e ombre."
L["Sky and water"] = "Cielo e acqua"
L["Clouds, fog, reflections and ripples."] = "Nuvole, nebbia, riflessi e increspature."
L["Effects"] = "Effetti"
L["Particles, glow, blood and sharpening."] = "Particelle, bagliore, sangue e nitidezza."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "Uscita HDR e luminosità."
L["Nameplate distance and zoom distance."] = "Distanza delle barre dei nomi e distanza dello zoom."
L["How far away grass and flowers start thinning out."] = "A che distanza erba e fiori iniziano a diradarsi."
L["How far the land is drawn in full; very demanding on frame rate."] = "Fin dove il terreno è disegnato per intero; molto pesante per il frame rate."
L["How far away trees, rocks and other objects keep their full detail."] = "Fino a che distanza alberi, rocce e altri oggetti mantengono il dettaglio pieno."
L["How far away small objects stay before they fade out."] = "Fino a che distanza restano visibili i piccoli oggetti prima di sparire."
L["How far away creatures and characters keep their full detail."] = "Fino a che distanza creature e personaggi mantengono il dettaglio pieno."
L["How far away nameplates show, in yards."] = "Fino a che distanza appaiono le barre dei nomi, in metri."
L["How far out you can zoom the camera."] = "Quanto puoi allontanare la telecamera."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "Più alto dà bordi delle ombre più nitidi, più basso fa risparmiare frame rate."
L["Horizon distance"] = "Distanza dell'orizzonte"
L["How far the flat horizon past the land reaches."] = "Fin dove arriva l'orizzonte piatto oltre il terreno."
L["Sky detail"] = "Dettaglio del cielo"
L["How detailed the clouds and sky are."] = "Quanto sono dettagliati nuvole e cielo."
L["Volumetric fog"] = "Nebbia volumetrica"
L["Fog with depth in place of the usual distance fog."] = "Nebbia con profondità al posto della solita nebbia in lontananza."
L["Water reflections"] = "Riflessi dell'acqua"
L["How much of the world water reflects."] = "Quanto del mondo riflette l'acqua."
L["Water ripples"] = "Increspature dell'acqua"
L["How detailed the ripples on water are."] = "Quanto sono dettagliate le increspature sull'acqua."
L["Particle density"] = "Densità delle particelle"
L["How many particles spells and effects show."] = "Quante particelle mostrano incantesimi ed effetti."
L["Full-screen glow"] = "Bagliore a schermo intero"
L["A soft glow around bright light."] = "Un leggero bagliore attorno alle luci forti."
L["Gray screen on death"] = "Schermo grigio alla morte"
L["The world turns gray while you're dead."] = "Il mondo diventa grigio mentre sei morto."
L["Blood and gore"] = "Sangue"
L["How much blood shows in fights, from none to the most."] = "Quanto sangue appare nei combattimenti, da nessuno al massimo."
L["Always sharpen"] = "Aumenta sempre la nitidezza"
L["Sharpens the picture even at full render scale."] = "Rende più nitida l'immagine anche con la scala di rendering piena."
L["HDR output"] = "Uscita HDR"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "Invia l'HDR al monitor; l'HDR di Windows deve essere attivo e Auto HDR disattivato."
L["Use peak brightness"] = "Usa la luminosità di picco"
L["Peak brightness"] = "Luminosità di picco"
L["Your monitor's peak brightness, in nits."] = "La luminosità di picco del tuo monitor, in nit."
L["HDR strength"] = "Intensità HDR"
L["How strong HDR is; works with peak brightness only."] = "Quanto è intenso l'HDR; funziona solo con la luminosità di picco."
L["Use reference brightness"] = "Usa la luminosità di riferimento"
L["Reference brightness"] = "Luminosità di riferimento"
L["How bright white looks in HDR, in nits."] = "Quanto è luminoso il bianco in HDR, in nit."
L["Sky and weather"] = "Cielo e meteo"
L["Water"] = "Acqua"
L["Restart graphics"] = "Riavvia la grafica"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Riavvia la grafica del gioco senza uscire; lo schermo diventa nero per un attimo."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Suoni e musica durante CineMode; le tue impostazioni audio tornano dopo."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Fa partire la musica quando una telecamera si avvia in CineMode e la sfuma quando torna l'interfaccia."
L["Pick where and when music can play in CineMode."] = "Scegli dove e quando la musica può partire in CineMode."
L["After a camera starts music, no camera starts it again for this long."] = "Dopo che una telecamera avvia la musica, nessuna telecamera la riavvia per questo tempo."
L["Fades music out once you leave the camera modes and move on."] = "Sfuma la musica quando esci dalle modalità telecamera e riparti."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Ogni riga è una scena che avvia la sua telecamera quando scatta uno dei suoi attivatori."
L["Lets the scenes below play their cameras when their triggers happen."] = "Permette alle scene qui sotto di avviare le loro telecamere quando scattano i loro attivatori."
L["Auto-running in walk mode."] = "Corsa automatica in modalità camminata."
L["Auto-running."] = "Corsa automatica."
L["Dying, until you release or are resurrected."] = "Morire, finché non liberi lo spirito o vieni resuscitato."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "Un PNG che parla con te o con il tuo gruppo; la telecamera si gira verso chi parla."
L["Other NPCs talking near you, once you've stood still a while."] = "Altri PNG che parlano vicino a te, dopo che sei rimasto fermo un po'."
L["Starts music as this camera starts; needs the Audio page on."] = "Fa partire la musica all'avvio di questa telecamera; richiede la pagina Audio attiva."
L["Plays a song of its own while the death camera runs."] = "Riproduce un brano tutto suo mentre è attiva la telecamera di morte."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "Attiva CineMode mentre questa telecamera è in funzione, quando Inizia in CineMode è disattivato."
L["Buff names or spell IDs, separated by commas."] = "Nomi di effetti o ID di incantesimi, separati da virgole."
L["Words in an object's name that mark it as a seat, separated by commas."] = "Parole nel nome di un oggetto che lo indicano come sedile, separate da virgole."
L["How long you stand still before this row's camera starts."] = "Quanto resti fermo prima che parta la telecamera di questa riga."
L["How long the camera waits on a quest window before it starts."] = "Quanto aspetta la telecamera su una finestra di missione prima di partire."
L["How long the camera waits on the window before it starts."] = "Quanto aspetta la telecamera sulla finestra prima di partire."
L["How long you stand still before NPCs chatting nearby start this camera."] = "Quanto resti fermo prima che i PNG che chiacchierano vicino avviino questa telecamera."
L["How long you keep going before this row's camera starts."] = "Quanto continui a muoverti prima che parta la telecamera di questa riga."
L["Whether this row's camera may start in or after a fight."] = "Se la telecamera di questa riga può partire durante o dopo un combattimento."
L["Where this row's camera may start."] = "Dove può partire la telecamera di questa riga."
L["Pause cameras while a window is open"] = "Metti in pausa le telecamere con una finestra aperta"
L["Scenes pause while a window like the map or spellbook is open."] = "Le scene vanno in pausa mentre è aperta una finestra come la mappa o il libro degli incantesimi."
L["Lists the rows by camera name or by scene name."] = "Elenca le righe per nome della telecamera o della scena."
L["Make a scene of your own with its triggers, camera and end."] = "Crea una scena tua con i suoi attivatori, telecamera e fine."
L["A scene of your own; open it to set its triggers and when it ends."] = "Una scena tua; aprila per impostare i suoi attivatori e quando finisce."
L["Copies this row just below, so you can give it another camera."] = "Copia questa riga subito sotto, così puoi darle un'altra telecamera."
L["Deletes this scene so it starts no camera."] = "Elimina questa scena, così non avvia nessuna telecamera."
L["Your own name for this row, shown on the grid."] = "Un nome tuo per questa riga, mostrato nella griglia."
L["The camera this row starts."] = "La telecamera che questa riga avvia."
L["This row's camera may start anywhere."] = "La telecamera di questa riga può partire ovunque."
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "Al chiuso, le modalità telecamera si allontanano e oscillano meno per non urtare i muri."
L["How far past your own distance the slow zoom may pull back indoors."] = "Quanto oltre la tua distanza può allontanarsi lo zoom lento al chiuso."
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "Impedisce alla telecamera AFK di girarti attorno al chiuso, dove può urtare i muri."
L["Shows it whenever its frame shows, hovered or not."] = "Visibile ogni volta che lo è il suo riquadro, col mouse sopra o no."
L["Shows it the whole time, CineMode or not."] = "Visibile sempre, con CineMode o senza."
L["CineMode hides everything: pick which frames show, and when."] = "CineMode nasconde tutto: scegli quali riquadri mostrare, e quando."
L["CineMode hides everything: tick which frames show, and when."] = "CineMode nasconde tutto: spunta quali riquadri mostrare, e quando."
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode nasconde questi riquadri, e li mostra solo quando lo dicono le loro righe."
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode nasconde i riquadri di questa sezione, e li mostra solo quando lo dicono le loro righe."
L["Not in use"] = "Non in uso"
L["Shows or hides its parts."] = "Mostra o nasconde le sue parti."
L["Shows the same parts as the Target rows."] = "Mostra le stesse parti delle righe Bersaglio."
L["Raid-style party frames follow the Raid tab's rows."] = "I riquadri del gruppo in stile incursione seguono le righe della scheda Incursione."
