L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "La tua disposizione della Modalità Modifica non ha spuntato Usa riquadri del gruppo in stile incursione."
L["Hide keybinds"] = "Nascondi i tasti"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "Nasconde i nomi dei tasti sui pulsanti delle barre delle azioni (1, a-Q, s-2...), con CineMode o senza."
L["Hide macro names"] = "Nascondi i nomi delle macro"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "Nasconde i nomi delle macro sui pulsanti delle barre delle azioni, con CineMode o senza."
L["Show while the spellbook is open"] = "Mostra con il libro degli incantesimi aperto"
L["Keeps your action bars up while the spellbook or macros window is open."] = "Tiene visibili le barre delle azioni mentre è aperto il libro degli incantesimi o la finestra delle macro."
