L["CineMode hides your buffs and debuffs: pick when they show."] = "CineMode nasconde i tuoi effetti benefici e penalizzanti: scegli quando mostrarli."
L["CineMode hides timers and meters: pick which show, and when."] = "CineMode nasconde timer e misuratori: scegli quali mostrare, e quando."
