L["CineMode hides the raid-style party frames: pick when they show."] = "CineMode nasconde i riquadri del gruppo in stile incursione: scegli quando mostrarli."
L["CineMode hides your character's highlight: pick when it shows."] = "CineMode nasconde l'evidenziazione del tuo personaggio: scegli quando mostrarla."
