L["Pick where chat bubbles show."] = "Scegli dove appaiono i fumetti della chat."
L["Pick where and when each kind of bubble shows."] = "Scegli dove e quando appare ogni tipo di fumetto."
L["These bubbles show everywhere, in fights and out."] = "Questi fumetti appaiono ovunque, in combattimento e fuori."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "Cinematic disegna fumetti propri per le parole il cui fumetto del gioco non puoi vedere."
L["Shows speech from someone off screen in a bubble low on the screen."] = "Mostra le parole di qualcuno fuori dallo schermo in un fumetto in basso sullo schermo."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "Apre la pagina Stile dei fumetti della chat: l'aspetto dei fumetti fuori schermo e dove appaiono."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "Mostra anche le emote nei fumetti fuori schermo, invece che in chat."
L["Moves bubbles at the very top of the screen down where you can read them."] = "Sposta più in basso i fumetti in cima allo schermo, dove puoi leggerli."
L["Small helpers for getting around the world."] = "Piccoli aiuti per muoverti nel mondo."
L["Turns all the Quality of Life helpers on or off."] = "Attiva o disattiva tutti gli aiuti per la comodità."
L["Opens the character window when you drag gear out of your bags."] = "Apre la finestra del personaggio quando trascini equipaggiamento fuori dalle borse."
L["Adds a button to view the talents of someone you inspect."] = "Aggiunge un pulsante per vedere i talenti di chi ispezioni."
L["Adds a talent calculator button to your talents window to plan a build."] = "Aggiunge alla finestra dei talenti un pulsante calcolatore per pianificare una build."
L["Moves game windows away from the left edge so your character stays in view."] = "Allontana le finestre del gioco dal bordo sinistro così il tuo personaggio resta in vista."
L["Lets you drag the game's windows to move them."] = "Ti permette di trascinare le finestre del gioco per spostarle."
L["Adds an icon to chat windows to copy their text."] = "Aggiunge alle finestre di chat un'icona per copiarne il testo."
L["Keep chat history"] = "Mantieni la cronologia della chat"
L["Chat windows bring back their last lines after a reload or login."] = "Le finestre di chat recuperano le ultime righe dopo aver ricaricato o all'accesso."
L["Show the time on those lines"] = "Mostra l'ora su quelle righe"
L["Puts the time at the start of brought-back lines."] = "Mette l'ora all'inizio delle righe recuperate."
L["Show XP left to level"] = "Mostra i PE mancanti al livello"
L["Shows how much XP you still need for the next level."] = "Mostra quanti PE ti servono ancora per il livello successivo."
L["The camera zooms to the distance below when you log in or reload."] = "La telecamera va alla distanza qui sotto quando accedi o ricarichi."
L["The camera distance to start at."] = "La distanza iniziale della telecamera."
L["A button at the top of the screen that reloads the UI in one click."] = "Un pulsante in cima allo schermo che ricarica l'interfaccia con un clic."
L["Reopens the windows you had open after a reload."] = "Riapre le finestre che avevi aperte dopo aver ricaricato."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "Nasconde i numeri fluttuanti di danni e cure in CineMode fuori dal combattimento."
L["Hides the red error text while you're fighting."] = "Nasconde il testo rosso degli errori mentre combatti."
L["Hides the red error text while you're out of combat."] = "Nasconde il testo rosso degli errori mentre sei fuori dal combattimento."
L["Turns the Hunter helpers on or off."] = "Attiva o disattiva gli aiuti per il Cacciatore."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "Il clic destro su un nemico usa Tiro Automatico quando è abbastanza lontano."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "Mette per prima la pila di munizioni più piccola dopo Riordina le borse, così viene sparata per prima."
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "Aggiunge dai mercanti un pulsante Riempi che riempie la faretra di munizioni."
L["Keeps your pet frame up while your pet isn't happy."] = "Tiene visibile il riquadro del famiglio finché il famiglio non è felice."
L["The pet frame fades with the UI while a camera mode runs."] = "Il riquadro del famiglio si dissolve con l'interfaccia mentre è attiva una modalità telecamera."
L["Move Questie's nameplate icons"] = "Sposta le icone di Questie sulle barre"
L["Moves Questie's quest icons beside the name, where Cinematic's quest mark goes."] = "Sposta le icone delle missioni di Questie accanto al nome, dove va il segno di missione di Cinematic."
L["Move EnhanceQoL's nameplate quest marks"] = "Sposta i segni di EnhanceQoL sulle barre"
L["Keeps EnhanceQoL's quest marks up, beside the name where Cinematic's would go."] = "Tiene visibili i segni di missione di EnhanceQoL, accanto al nome dove andrebbero quelli di Cinematic."
