L["Turns Cinematic's support for your other addons on or off."] = "Attiva o disattiva il supporto di Cinematic per i tuoi altri addon."
L["Right-click casts Fishing again and the Fishing cast bar hides, as this page says."] = "Il clic destro rilancia Pesca e la barra di lancio di Pesca si nasconde, come dice questa pagina."
L["Hides your cast bar while you're fishing."] = "Nasconde la barra di lancio mentre peschi."
