-- Changelog.lua
L["A button on the main page puts Cinematic back to a fresh install."] = "Un pulsante nella pagina principale riporta Cinematic a com'era appena installato."
L["A fishing camera and settings of its own."] = "Una telecamera per la pesca con impostazioni proprie."
L["A new Interface hub"] = "Un nuovo gruppo Interfaccia"
L["A new welcome window"] = "Una nuova finestra di benvenuto"
L["Achievement progress cards"] = "Schede dei progressi delle imprese"
