-- Options.lua
L["Pick Always, < 100%, < 100% Calm or Off, or scroll over the box for other percentages."] = "Scegli Sempre, < 100%, < 100% Calma o Disattivato, oppure scorri sulla casella per altre percentuali."
L["Pick Always, < 100% or Off, or scroll over the box for other percentages."] = "Scegli Sempre, < 100% o Disattivato, oppure scorri sulla casella per altre percentuali."
L["Turns this page on or off, same as right-clicking its icon."] = "Attiva o disattiva questa pagina, come il clic destro sulla sua icona."
L["Put this page's settings back to your profile's defaults?"] = "Riportare le impostazioni di questa pagina ai valori predefiniti del tuo profilo?"
L["Put these settings back to your profile's defaults?"] = "Riportare queste impostazioni ai valori predefiniti del tuo profilo?"
L["|cff808080Searching...|r"] = "|cff808080Ricerca in corso...|r"
L["Allow offscreen nameplates in CineMode"] = "Barre dei nomi fuori schermo in CineMode"
L["Keeps plates for people behind you, so Heal Vision and Emote Vision see them too."] = "Tiene le barre di chi sta dietro di te, così anche Heal Vision ed Emote Vision li vedono."
L["Only where Heal Vision or Emote Vision use them."] = "Solo dove le usano Heal Vision o Emote Vision."
L["All through CineMode."] = "Per tutto il CineMode."
L["Cinematic never turns them on."] = "Cinematic non le attiva mai."
L["CineMode turns on by itself between fights and fades the UI."] = "CineMode si attiva da solo tra un combattimento e l'altro e dissolve l'interfaccia."
L["Walking or riding around brings the UI back."] = "Camminare o cavalcare riporta l'interfaccia."
L["Use a Show in row instead"] = "Usa invece una riga Mostra in"
L["The row below picks where CineMode exits, in place of the boxes above."] = "La riga qui sotto sceglie dove esci da CineMode, al posto delle caselle qui sopra."
L["Keeps CineMode off everywhere."] = "Tiene CineMode disattivato ovunque."
L["Sweeps turn the other way."] = "Le panoramiche girano dall'altra parte."
L["Each time, the camera picks clockwise or counterclockwise at random."] = "Ogni volta la telecamera sceglie a caso se girare in senso orario o antiorario."
L["Put this camera's settings back to your profile's defaults?"] = "Riportare le impostazioni di questa telecamera ai valori predefiniti del tuo profilo?"
L["Now and then the camera turns around to look back past you."] = "Ogni tanto la telecamera si gira per guardare indietro, oltre te."
L["How far the camera turns around, where 180 looks straight back at you."] = "Quanto si gira la telecamera: con 180 guarda dritto verso di te."
L["How long the turn around takes, speeding up and slowing down."] = "Quanto dura la giravolta, tra accelerazione e frenata."
L["As you land, the camera zooms back to the zoom you had at takeoff."] = "Quando atterri, la telecamera torna allo zoom che avevi al decollo."
L["The camera sways slowly from side to side around where it started, pausing between moves."] = "La telecamera ondeggia piano da un lato all'altro attorno al punto di partenza, con qualche pausa."
L["Once it has turned halfway around, the camera sways slowly from side to side."] = "Dopo mezzo giro, la telecamera ondeggia piano da un lato all'altro."
L["When you /stare at the view, the camera sways very slightly from where it is."] = "Quando usi /stare per guardare il panorama, la telecamera ondeggia appena da dov'è."
L["The camera sways very slightly from side to side."] = "La telecamera ondeggia appena da un lato all'altro."
L["While you fish, the camera sways a little and keeps your bobber in view."] = "Mentre peschi, la telecamera ondeggia un po' e tiene in vista il galleggiante."
L["While you auto-walk, the camera drifts slowly along with you."] = "Mentre cammini in automatico, la telecamera scivola piano insieme a te."
L["Each death, the camera picks clockwise or counterclockwise at random."] = "A ogni morte la telecamera sceglie a caso se girare in senso orario o antiorario."
L["The camera zooms in to this distance if you're farther out."] = "Se sei più lontano, la telecamera si avvicina fino a questa distanza."
L["Which side of you the camera moves to."] = "Da che lato di te si sposta la telecamera."
L["The camera turns to the side as it zooms in, then tilts down."] = "La telecamera gira di lato mentre si avvicina, poi si inclina verso il basso."
L["How fast the spin speeds up after the first half turn."] = "Quanto accelera la rotazione dopo il primo mezzo giro."
L["As it turns, the camera also drops toward the ground. Negative values raise it instead."] = "Mentre gira, la telecamera scende anche verso terra. Con valori negativi invece sale."
L["The camera starts zooming in when the cast starts, and is still zooming in as you leave."] = "La telecamera inizia ad avvicinarsi quando parte il lancio, e lo fa ancora mentre te ne vai."
L["How fast the camera zooms back out to your own distance if you cancel the cast."] = "Quanto in fretta la telecamera torna alla tua distanza se annulli il lancio."
L["Load Atmosphere"] = "Carica Atmosfera"
L["Unticked, Atmosphere doesn't load at all (takes a reload)."] = "Senza spunta, Atmosfera non si carica proprio (serve un ricaricamento)."
L["Tick it and reload to bring every Atmosphere page back."] = "Spuntala e ricarica per riavere tutte le pagine di Atmosfera."
L["Turn off to keep Atmosphere from loading at all."] = "Disattivala perché Atmosfera non si carichi proprio."
L["Atmosphere isn't loaded: no tint, letterbox, haze, Graphics Boost or music runs, and their pages are gone."] = "Atmosfera non è caricata: niente tinta, bande nere, foschia, Potenziamento grafico o musica, e le loro pagine non ci sono."
L["How the game world looks in CineMode: vignette, inn glow and depth of field."] = "L'aspetto del mondo di gioco in CineMode: vignettatura, luce della locanda e profondità di campo."
L["Haze"] = "Foschia"
L["Darkens the edges of the screen."] = "Scurisce i bordi dello schermo."
L["Shows the vignette for a few seconds, in CineMode or not."] = "Mostra la vignettatura per qualche secondo, in CineMode o no."
L["A warm firelight glow, brightest low on the screen."] = "Una calda luce di fuoco, più forte in basso sullo schermo."
L["Shows the glow for a few seconds, in CineMode or not."] = "Mostra la luce per qualche secondo, in CineMode o no."
L["Haze strength"] = "Intensità della foschia"
L["A light haze around the edges of the screen."] = "Una leggera foschia attorno ai bordi dello schermo."
L["Shows the haze at this strength for a few seconds, in CineMode or not."] = "Mostra la foschia a questa intensità per qualche secondo, in CineMode o no."
L["How they look"] = "Il loro aspetto"
L["Style pages:"] = "Pagine Stile:"
L["The tint's preset, time of day and zone moods."] = "La preimpostazione della tinta, l'ora del giorno e l'atmosfera delle zone."
L["Each weather's color, and how fast it comes in."] = "Il colore di ogni meteo, e quanto in fretta arriva."
L["Music can play any time in CineMode, so the other columns don't matter."] = "La musica può partire in qualsiasi momento in CineMode, quindi le altre colonne non contano."
L["Load Cameras"] = "Carica Telecamere"
L["Unticked, Cinematic's cameras don't load at all (takes a reload)."] = "Senza spunta, le telecamere di Cinematic non si caricano proprio (serve un ricaricamento)."
L["Tick it and reload to bring every camera back."] = "Spuntala e ricarica per riavere tutte le telecamere."
L["Turn off to keep the cameras from loading at all."] = "Disattivala perché le telecamere non si carichino proprio."
L["Cameras aren't loaded: none of them run, and their pages are gone."] = "Le telecamere non sono caricate: nessuna parte, e le loro pagine non ci sono."
L["In CineMode, the camera moves on its own when things happen, like emotes, flights or going AFK."] = "In CineMode la telecamera si muove da sola quando succede qualcosa, come un'emote, un volo o andare AFK."
L["Move this row up so its trigger tries it sooner."] = "Sposta su questa riga perché il suo attivatore la provi prima."
L["Move this row down so its trigger tries it later."] = "Sposta giù questa riga perché il suo attivatore la provi dopo."
L["Uses this row. Untick it and its trigger skips it."] = "Usa questa riga. Togli la spunta e il suo attivatore la salta."
L["Turns this section on or off. When it's off, CineMode leaves its frames alone."] = "Attiva o disattiva questa sezione. Quando è disattivata, CineMode lascia stare i suoi riquadri."
L["CineMode hides the range hint: pick when it shows."] = "CineMode nasconde l'indicatore di portata: scegli quando si vede."
L["When the XP bar, bags, micro menu and similar frames show."] = "Quando si vedono la barra dell'esperienza, le borse, il micromenu e riquadri simili."
L["How the damage and healing numbers over heads look."] = "L'aspetto dei numeri di danni e cure sopra le teste."
L["Shows chat bubbles where this page says. When it's off, the game's own settings are used."] = "Mostra i fumetti della chat dove dice questa pagina. Quando è disattivata, valgono le impostazioni del gioco."
L["Windows"] = "Finestre"
L["Open windows clear of your character"] = "Apri le finestre lontano dal personaggio"
L["Dead center instead"] = "Invece al centro esatto"
L["Opens them in the very middle of the screen."] = "Le apre proprio al centro dello schermo."
L["Forget where you dragged the windows, so each opens in its usual place again."] = "Dimentica dove hai trascinato le finestre, così ognuna si riapre al suo solito posto."
L["Dressing room beside the Auction House"] = "Camerino accanto alla Casa d'Aste"
L["Ctrl+Click an auction to see it on you without the Auction House closing."] = "Ctrl+Clic su un'asta per provartela addosso senza chiudere la Casa d'Aste."
L["Gear and talents"] = "Equipaggiamento e talenti"
L["Off by default because it can cause harmless errors in error-catching addons."] = "Disattivato di base perché può causare errori innocui negli addon che raccolgono errori."
L["Login and reload"] = "Accesso e ricaricamento"
L["Open the AddOns list on All"] = "Apri l'elenco AddOn su Tutti"
L["The game's AddOns list starts on All instead of just this character."] = "L'elenco AddOn del gioco parte da Tutti invece che solo da questo personaggio."
L["Text on screen"] = "Testo sullo schermo"
L["Cast and reel in with the mouse or a gamepad, in CineMode or not."] = "Lancia e tira su la lenza col mouse o col controller, in CineMode o no."
L["The game's sound effects volume while you fish. The splash of a bite is a sound effect."] = "Il volume degli effetti sonori del gioco mentre peschi. Lo splash di un pesce che abbocca è un effetto sonoro."
L["Show in fights, and after them until the Calm Timer runs out."] = "Visibile in combattimento, e dopo finché non scade il Timer di calma."
