L["Show out in the world, inns included. Capital cities count as Cities."] = "Visibile nel mondo, locande comprese. Le capitali contano come Città."
L["Enemies in ~30 yd"] = "Nemici entro ~30 m"
L[" The nameplate of the unit under your mouse, whatever the Nameplates grid says."] = " La barra del nome dell'unità sotto il mouse, qualunque cosa dica la griglia Barre dei nomi."
L[" Hostile NPCs and enemy players within about 30 yards (your spell nearest 30 yards), whatever their rows say."] = " PNG ostili e giocatori nemici entro circa 30 metri (il tuo incantesimo più vicino ai 30 metri), qualunque cosa dicano le loro righe."
L[" The glow when a mob is targeting you or about to."] = " Il bagliore quando un mostro ti prende di mira o sta per farlo."
L["Far, behind walls"] = "Lontani, dietro i muri"
L["%d%%"] = "%d%%"
L["Past 28 yards, how much of a title still shows when the game thinks it's behind a wall. 0 hides it."] = "Oltre 28 m, quanto si vede ancora un titolo quando il gioco pensa che sia dietro un muro. 0 lo nasconde."
L["Mouseover nameplates"] = "Barre al passaggio del mouse"
L["Target names"] = "Nomi del bersaglio"
L[" The name of the unit under your mouse, even with its kind's names off."] = " Il nome dell'unità sotto il mouse, anche se i nomi del suo tipo sono disattivati."
