L[" Every other names row shows only where this one does."] = " Ogni altra riga dei nomi si vede solo dove si vede questa."
L["Names look as this page says. When it's off, they look the way the nameplate draws them."] = "I nomi hanno l'aspetto che dice questa pagina. Quando è disattivata, appaiono come li disegna la barra del nome."
L["Every plate that no row above fits."] = "Ogni barra che non rientra in nessuna riga qui sopra."
