L["Tooltips show the whole time in CineMode, so the other columns don't matter."] = "I tooltip si vedono sempre in CineMode, quindi le altre colonne non contano."
L["The zone under a party member's class when they're out of sight (\"Stormwind City\")."] = "La zona sotto la classe di un membro del gruppo quando è lontano (\"Roccavento\")."
