L["CineMode hides these addons' frames. Pick which ones show, and when."] = "CineMode nasconde i riquadri di questi addon. Scegli quali si vedono, e quando."
L["Addons you install later always show in CineMode to start with."] = "Gli addon che installi dopo all'inizio si vedono sempre in CineMode."
L["Does what Load does for every frame on this list that isn't loaded yet."] = "Fa quello che fa Carica per ogni riquadro dell'elenco non ancora caricato."
