L["Cinematic's page comes up when the fight ends"] = "La pagina di Cinematic si apre a fine combattimento"
L["Put the profile %s back to how it started? Every change you've made to it will be lost."] = "Riportare il profilo %s com'era all'inizio? Perderai tutte le modifiche che gli hai fatto."
L["Put the profile %s back to how you last saved it? Changes you've made since then will be lost."] = "Riportare il profilo %s a come l'hai salvato l'ultima volta? Perderai le modifiche fatte da allora."
L["Pointing at a faded frame shows it, along with the other frames in its groups."] = "Puntare un riquadro dissolto lo mostra, insieme agli altri riquadri dei suoi gruppi."
L["Right-click to go back to its own icon."] = "Clic destro per tornare alla sua icona."
L["Floating text changes after you log out and back in (/reload isn't enough). The same goes for getting it back: until you log out it stays hidden, even with Cinematic turned off."] = "Il testo fluttuante cambia dopo che esci e rientri (/reload non basta). Lo stesso vale per riaverlo: finché non esci resta nascosto, anche con Cinematic disattivato."
L["Style isn't loaded: no Style page or look runs, and their pages are gone."] = "Stile non è caricato: nessuna pagina o aspetto di Stile è attivo, e le loro pagine non ci sono."

-- ProfilerPage.lua
L["It's off. Right-click the Profiler icon to start sampling."] = "È spento. Clic destro sull'icona del Profiler per iniziare a registrare."
L["What the game measured for Cinematic over the same time, including what the timers don't cover."] = "Quello che il gioco ha misurato per Cinematic nello stesso tempo, compreso ciò che i timer non coprono."
L["Memory used and thrown away each second. The game spends time cleaning it up."] = "Memoria usata e buttata ogni secondo. Il gioco perde tempo a ripulirla."
L["(Called by the part above, so its time is counted in that one.)"] = "(Chiamata dalla parte qui sopra, quindi il suo tempo è contato in quella.)"

-- RuleAxes.lua
L["open now"] = "aperta ora"

-- Slash.lua
L["the camera turns once around you: 360 degrees over 10 seconds unless you give a number (a negative one turns the other way); again stops it"] = "la telecamera ti fa un giro attorno: 360 gradi in 10 secondi, se non dai un numero (uno negativo gira dall'altra parte); ripeterlo la ferma"
L["show or hide the keyboard map: what each of your keys does (add words to find them on it)"] = "mostra o nasconde la mappa della tastiera: cosa fa ogni tuo tasto (aggiungi parole per cercarli)"
L["fade the frame you're hovering over too (or /cine add <FrameName>)"] = "dissolvi anche il riquadro sotto il mouse (o /cine add <NomeRiquadro>)"
L["your damage report for this run: boss by boss, the rest, the whole party (test shows a made-up one)"] = "il tuo resoconto dei danni per questa spedizione: boss per boss, il resto, tutto il gruppo (test ne mostra uno inventato)"
L["record what the addon costs, results on the Profiler page (add deep for more detail, or stop to end it early)"] = "registra quanto pesa l'addon, risultati nella pagina Profiler (aggiungi deep per più dettagli, o stop per finire prima)"
L["%d matches for \"%s\", best: \"%s\" (%s). Pick one in the results window."] = "%d risultati per \"%s\", il migliore: \"%s\" (%s). Scegline uno nella finestra dei risultati."
