-- Atmosphere/LowHealth.lua
L["That isn't the whole thing. Copy it again, all of it."] = "Non è completo. Copialo di nuovo, tutto intero."
L["At what health the edges close in, and how fast."] = "A che livello di salute si chiudono i bordi, e quanto in fretta."
L["The color of a big hit's flash, and the color the world fades to."] = "Il colore del lampo di un colpo forte, e il colore verso cui sbiadisce il mondo."
L["This theme's heartbeat speed, relative to Beats a minute above. A creeping theme beats slower."] = "La velocità del battito di questo tema, rispetto a Battiti al minuto qui sopra. Un tema strisciante batte più piano."
L["How much this theme throbs, relative to Throb above."] = "Quanto pulsa questo tema, rispetto a Pulsazione qui sopra."
L["The theme's art that spreads in from the edges."] = "La grafica del tema che si allarga dai bordi."
L["The glow around the art, added as light. This is Glow's only color."] = "Il bagliore attorno alla grafica, aggiunto come luce. È l'unico colore di Bagliore."
L["How strong the glow is compared to the art."] = "Quanto è forte il bagliore rispetto alla grafica."
L["The theme's art (blood, smoke, a glow) that spreads in from the edges as they close in."] = "La grafica del tema (sangue, fumo, un bagliore) che si allarga dai bordi mentre si chiudono."
L["How many appear per minute at full strength. A big hit adds a few more."] = "Quanti ne appaiono al minuto alla massima intensità. Un colpo forte ne aggiunge qualcuno."
L["How big they are compared to normal."] = "Quanto sono grandi rispetto al normale."
L["How strong it is at full, multiplied by the art's opacity."] = "Quanto è forte al massimo, moltiplicato per l'opacità della grafica."
L["Overall strength, reach and brightness, plus the shadow, the heartbeat and big hits."] = "Intensità, estensione e luminosità generali, più l'ombra, il battito e i colpi forti."
L["How the screen looks as your mana runs out."] = "L'aspetto dello schermo quando il mana finisce."
L["As your health drops, the edges of the screen close in."] = "Quando la salute cala, i bordi dello schermo si chiudono."
L["Shows everywhere, so the other columns don't change anything."] = "Si vede ovunque, quindi le altre colonne non cambiano niente."
L["The edges start closing in when your health drops below this."] = "I bordi iniziano a chiudersi quando la salute scende sotto questo valore."
L["The edges are all the way in when your health drops to this. Keep it below Starts."] = "I bordi sono chiusi del tutto quando la salute scende a questo valore. Tienilo sotto Inizio."
L["How much of your health one hit has to take to count as a big hit."] = "Quanta salute deve toglierti un colpo per contare come colpo forte."
L["As your mana runs out, the screen drains. Right-click the tab to turn it on."] = "Quando il mana finisce, lo schermo si svuota di colore. Clic destro sulla scheda per attivarlo."

-- Atmosphere/ManaVision.lua
L["Low mana"] = "Mana basso"
L["The screen starts to drain when your mana drops below this."] = "Lo schermo inizia a svuotarsi quando il mana scende sotto questo valore."
L["The screen is fully drained when your mana drops to this. Keep it below Starts."] = "Lo schermo è del tutto svuotato quando il mana scende a questo valore. Tienilo sotto Inizio."
L["How strong it is out of a fight."] = "Quanto è forte fuori dal combattimento."
L["Shows your mana running out on the screen."] = "Mostra sullo schermo il mana che finisce."
L["This character doesn't use mana, so nothing shows."] = "Questo personaggio non usa mana, quindi non si vede niente."
L["Drained"] = "Svuotato"
L["Gray-blue: the world's color drains away."] = "Grigio-blu: il colore del mondo svanisce."
L["Cold"] = "Freddo"
L["A cold, deep blue."] = "Un blu freddo e profondo."
L["A dim, gray-violet dusk."] = "Un crepuscolo cupo, grigio-viola."
L["How strong the veil and the edges are when your mana is out."] = "Quanto sono forti il velo e i bordi quando il mana è finito."
L["Dark edges"] = "Bordi scuri"
L["Dark edges close in as your mana runs out."] = "Bordi scuri si chiudono quando il mana finisce."
L["How far in from the screen's edges they come."] = "Quanto entrano dai bordi dello schermo."
L["Shows your mana running out in the preview and on screen."] = "Mostra il mana che finisce nell'anteprima e sullo schermo."

-- Atmosphere/TeleportVision.lua
L["Motes in the portal's color drift in from the rim."] = "Granelli del colore del portale arrivano fluttuando dal bordo."
L["Plays a pretend 8-second cast on screen. Close the settings to see it."] = "Mostra sullo schermo un finto lancio di 8 secondi. Chiudi le impostazioni per vederlo."

-- Atmosphere/Tint.lua
L["Warm brownish yellow, like an old photo. The world can't be fully desaturated."] = "Giallo caldo tendente al marrone, come una vecchia foto. Il mondo non può perdere del tutto il colore."
L["A warm haze over everything."] = "Una foschia calda su tutto."

-- Camera/CameraManager.lua
L["Right-click to copy it, or to rename, describe, change the icon of or delete one of yours."] = "Clic destro per copiarla, o per rinominare, descrivere, cambiare icona o eliminare una delle tue."
L["Makes a copy of this camera's script for you to change, and opens its tab."] = "Crea una copia dello script di questa telecamera da modificare, e apre la sua scheda."

-- Camera/CameraScriptsPage.lua
L["Runs when the camera ends, whatever ends it (its stop rules say what does). Every camera has one and it can't be removed. Pick it and add steps to put them inside."] = "Parte quando la telecamera finisce, qualunque cosa la faccia finire (lo dicono le sue regole di stop). Ogni telecamera ne ha uno e non si può togliere. Selezionalo e aggiungi passi per metterli dentro."
L["Lets scenes play your scripts, and lets our cameras use your changes to their scripts."] = "Permette alle scene di usare i tuoi script, e alle nostre telecamere di usare le tue modifiche ai loro script."
L["This script as text to share with friends."] = "Questo script come testo da condividere con gli amici."
L["A haze around the edges of the screen while this camera runs. Set to 0 to turn it off."] = "Una foschia attorno ai bordi dello schermo mentre va questa telecamera. Metti 0 per toglierla."
L["A built-in camera you've changed. Reset puts ours back."] = "Una telecamera di base che hai modificato. Ripristina rimette la nostra."
L["A built-in camera, made from your settings. Any change you make saves it as your own."] = "Una telecamera di base, fatta con le tue impostazioni. Qualsiasi modifica la salva come tua."

-- Camera/CameraTriggerEditor.lua
L["Another trigger for this scene. Any one of its triggers starts it."] = "Un altro attivatore per questa scena. Basta uno qualsiasi dei suoi attivatori per avviarla."
L["Turns CineMode on while its camera runs, if Start in CineMode is off."] = "Attiva CineMode mentre va la sua telecamera, se Inizia in CineMode è disattivato."

-- Camera/ShotsPage.lua
L["Copies text you can send a friend, who adds this shot with Import here or on their Scenes page."] = "Copia un testo da mandare a un amico, che aggiunge questa inquadratura con Importa qui o nella sua pagina Scene."
L["The camera whose moves this shot uses."] = "La telecamera di cui questa inquadratura usa i movimenti."
L["Clears this shot's numbers so they go back to its camera's own settings."] = "Cancella i numeri di questa inquadratura, così tornano alle impostazioni della sua telecamera."

-- Camera/ShoulderCalibrate.lua
L["Stops using this measurement and goes back to the built-in size."] = "Smette di usare questa misura e torna alla dimensione di base."

-- Camera/ShoulderCam.lua
L["Another addon (DynamicCam) is running a shoulder camera, so the Shoulder Cam stays off."] = "Un altro addon (DynamicCam) sta usando una telecamera alle spalle, quindi la Shoulder Cam resta spenta."
L["Shoulder Cam uses some experimental Blizzard features, as well as some hacks to fill in the gaps."] = "La Shoulder Cam usa alcune funzioni sperimentali di Blizzard, più qualche trucco per coprire i buchi."
L["Which frames slide with you while the camera is over your shoulder."] = "Quali riquadri si spostano con te mentre la telecamera è alle tue spalle."
L["Which of Cinematic's cameras keep the Shoulder Cam on while they play."] = "Quali telecamere di Cinematic tengono accesa la Shoulder Cam mentre vanno."
L["Over your shoulder everywhere, so the other columns don't matter."] = "Alle tue spalle ovunque, quindi le altre colonne non contano."
L["How far from the middle you sit when zoomed out. Set it lower than Spot on screen to keep the camera from catching on walls, which only happens zoomed out."] = "Quanto stai lontano dal centro con lo zoom indietro. Mettila più bassa di Posizione sullo schermo perché la telecamera non urti i muri, cosa che succede solo con lo zoom indietro."
L["The camera distance where you reach Spot zoomed out. Between 5 yards and this distance, you slide from Spot on screen to Spot zoomed out."] = "La distanza della telecamera a cui arrivi a Posizione con zoom indietro. Tra 5 metri e questa distanza, passi piano da Posizione sullo schermo a Posizione con zoom indietro."
L["Keep the shoulder when selecting yourself"] = "Resta alle spalle se selezioni te stesso"
L["Selecting yourself clears your target instead, so the camera stays over your shoulder. Heals and buffs still land on you."] = "Selezionare te stesso invece toglie il bersaglio, così la telecamera resta alle tue spalle. Cure ed effetti benefici arrivano comunque a te."
L["Shows our own copy of your target frame, so it matches only the game's look or a Cinematic theme."] = "Mostra una nostra copia del riquadro del bersaglio, così segue solo l'aspetto del gioco o un tema di Cinematic."
L["How long the Shoulder Cam waits to come back over your shoulder after you step outside or get off your mount. Going back in or mounting again during the wait starts it over."] = "Quanto aspetta la Shoulder Cam prima di tornare alle tue spalle quando esci all'aperto o scendi dalla cavalcatura. Se rientri o rimonti durante l'attesa, si ricomincia da capo."
L["Turns to who you talk to everywhere, so the other columns don't matter."] = "Si gira verso chi ti parla ovunque, quindi le altre colonne non contano."
L["How many seconds the camera takes to move behind you for this camera. Leave it empty to use %s."] = "Quanti secondi ci mette la telecamera a portarsi dietro di te per questa telecamera. Lascia vuoto per usare %s."

-- Camera/SkyrideCam.lua
L["Everywhere you skyride, so the other columns don't matter."] = "Ovunque voli col volo dinamico, quindi le altre colonne non contano."
L["How far past your cruise distance (set in Take off) the camera goes."] = "Quanto va oltre la tua distanza di crociera (impostata in Decollo) la telecamera."
L["At 0.5 it's a snap, as fast as the game's zoom can go."] = "A 0.5 è uno scatto, veloce quanto lo zoom del gioco."
L["How close the camera comes in. Set to 0 to keep its distance."] = "Quanto si avvicina la telecamera. Metti 0 per non cambiare distanza."
L["Second Wind brings the camera in a little, then back out."] = "Secondo Respiro avvicina un po' la telecamera, poi la riallontana."
L["The fastest the camera can move. Moves that would go faster take longer instead."] = "La velocità massima della telecamera. I movimenti che andrebbero più veloci durano di più."
L["Blends one move into the next. At 0 the camera stops between moves."] = "Fonde un movimento nel successivo. A 0 la telecamera si ferma tra un movimento e l'altro."

-- Camera/TriggersPage.lua
L["For now, its camera follows its own rules for when it plays."] = "Per ora la sua telecamera segue le sue regole per quando partire."
L["Moves it up, so it wins over the one above."] = "Lo sposta su, così vince su quello sopra."
L["Moves it down, so the one below wins over it."] = "Lo sposta giù, così quello sotto vince su di lui."
L["Makes a copy of this trigger that you can change on its own."] = "Crea una copia di questo attivatore da modificare per conto suo."
L["Puts its Only if, wait, cooldown, chance and priority back to how they came."] = "Riporta Solo se, attesa, tempo di recupero, probabilità e priorità a com'erano all'inizio."
L["A wait before it starts, a minimum time, a cooldown and a chance."] = "Un'attesa prima di partire, una durata minima, un tempo di recupero e una probabilità."
L["A rule that must be true for it to start. Leave it empty to always start. Click to edit."] = "Una regola che deve essere vera perché parta. Lascia vuoto per partire sempre. Clicca per modificarla."
L["When on, it waits until its condition is no longer true before it can start again."] = "Se attivo, aspetta che la sua condizione non sia più vera prima di poter ripartire."

