-- Profiles/Welcome.lua
L["Playing %s, %d of %d"] = "In riproduzione: %s, %d di %d"
L["Playing %s"] = "In riproduzione: %s"
L["Feature List: Click to preview"] = "Elenco funzioni: clicca per l'anteprima"
L["Watch the tour \194\183 1\194\189 min"] = "Guarda il tour \194\183 1\194\189 min"
L["The highlights one after another: %s. Stop any time."] = "Il meglio, uno dopo l'altro: %s. Puoi fermarti quando vuoi."
L["Puts the features you switched here back as the profile you're trying has them."] = "Riporta le funzioni che hai cambiato qui a come le ha il profilo che stai provando."
