L["%d switches of yours"] = "%d tue modifiche"
L["Turn %s off"] = "Disattiva %s"
L["Turn %s on"] = "Attiva %s"
L["Takes it out of %s, the profile you're trying."] = "La toglie da %s, il profilo che stai provando."
L["Adds it to %s, the profile you're trying."] = "La aggiunge a %s, il profilo che stai provando."
L["It uses one of Blizzard's experimental camera settings: turning it on agrees to that."] = "Usa un'impostazione sperimentale della telecamera di Blizzard: attivandola, la accetti."
L["You turned it on."] = "L'hai attivata tu."
L["You turned it off."] = "L'hai disattivata tu."
L["See all"] = "Vedi tutto"
L["Everything Cinematic can show you, by where you'll find it in the settings. Click any to see it."] = "Tutto quello che Cinematic può mostrarti, in base a dove lo trovi nelle impostazioni. Clicca su una voce per vederla."
L["Find a feature: fishing, duel, camera..."] = "Cerca una funzione: pesca, duello, telecamera..."
L["You're in a fight. The demos come back when it ends."] = "Sei in combattimento. Le demo tornano quando finisce."
L["Also in Cinematic:"] = "In Cinematic c'è anche:"
L["Nothing to play: click to open its settings. Closing them brings you back here."] = "Niente da mostrare: clicca per aprire le sue impostazioni. Chiudendole torni qui."
L["Nothing to play for that: it's a setting, below."] = "Niente da mostrare per questo: è un'impostazione, qui sotto."
L["Nothing called \"%s\" plays here."] = "Qui non c'è niente chiamato \"%s\" da mostrare."
L["Plays each in turn, a few seconds each. Stop any time."] = "Li mostra uno alla volta, qualche secondo ciascuno. Puoi fermarti quando vuoi."
L["See all %d"] = "Vedi tutti e %d"
L["%d more"] = "altri %d"
L["In a fight: demos wait till it ends."] = "In combattimento: le demo aspettano che finisca."
L["Stop the tour"] = "Ferma il tour"
L["Play these"] = "Mostra questi"
L["Play all"] = "Mostra tutto"
L["Play all in %s"] = "Mostra tutto in %s"
