-- Style/BubbleStyle.lua
L["Just the words, with no bubble. An outline makes them easier to read."] = "Solo le parole, senza fumetto. Un contorno le rende più leggibili."
L["How big speech from behind you is compared to a bubble overhead. Smaller makes it seem farther away."] = "Quanto sono grandi le parole dette alle tue spalle rispetto a un fumetto sopra la testa. Più piccole sembrano più lontane."
L["How solid speech from behind you looks. Fainter makes it seem muffled and out of view."] = "Quanto sono nette le parole dette alle tue spalle. Più tenui sembrano attutite e fuori vista."

-- Style/CdmStyle.lua
L["After a few hits"] = "Dopo qualche colpo"
L["Draining"] = "In svuotamento"
L["Just cast"] = "Appena lanciato"
L["Halfway"] = "A metà"
L["Cooldown Manager Style"] = "Stile del Gestore dei tempi di recupero"
L["How the drain ring on your tracked buffs looks. Pick which buffs get one on the Cooldown Manager page, under Look."] = "L'aspetto dell'anello che si svuota sugli effetti benefici che segui. Scegli quali lo hanno nella pagina Gestore dei tempi di recupero, sotto Aspetto."
L["Turns this page's ring look on or off. Off: the ring's own look."] = "Attiva o disattiva l'aspetto dell'anello di questa pagina. Disattivato: l'aspetto normale dell'anello."
L["How the drain ring on your tracked buffs looks."] = "L'aspetto dell'anello che si svuota sugli effetti benefici che segui."
L["The Cooldown Manager icons' shape."] = "La forma delle icone del Gestore dei tempi di recupero."
L["Cooldown + DoT"] = "Recupero + DoT"
L["How a spell's cooldown shows over its DoT, on rows whose Shows is Both."] = "Come appare il tempo di recupero di un incantesimo sopra il suo DoT, nelle righe con Visibili su Entrambi."
L["The icons take Action Bar Style's shape."] = "Le icone prendono la forma di Stile delle barre delle azioni."
L["Square icons, whatever the action buttons are."] = "Icone quadrate, comunque siano i pulsanti delle azioni."
L["Round icons, whatever the action buttons are."] = "Icone rotonde, comunque siano i pulsanti delle azioni."
L["Pips"] = "Tacche"
L["Eight chunky segments round the icon."] = "Otto segmenti spessi attorno all'icona."
L["One thin ring round the icon."] = "Un anello sottile attorno all'icona."
L["Liquid"] = "Liquido"
L["The icon empties from the top down."] = "L'icona si svuota dall'alto in basso."
L["Bar under"] = "Barra sotto"
L["A thin bar under the icon."] = "Una barra sottile sotto l'icona."
L["How big the ring is next to the icon."] = "Quanto è grande l'anello rispetto all'icona."
L["Empty part"] = "Parte vuota"
L["How dark the spent part shows. 0: hidden."] = "Quanto è scura la parte consumata. 0: nascosta."
L["The ring in your class's color."] = "L'anello nel colore della tua classe."
L["From the full end's color to the empty end's: what's left turns toward the empty color as it drains."] = "Dal colore dell'estremo pieno a quello dell'estremo vuoto: ciò che resta vira verso il colore vuoto man mano che si svuota."
L["The color you pick below."] = "Il colore che scegli qui sotto."
L["A plain white ring."] = "Un semplice anello bianco."
L["Click to choose the ring's color."] = "Clicca per scegliere il colore dell'anello."
L["Full end"] = "Estremo pieno"
L["The gradient's color where the shield is full."] = "Il colore della sfumatura dove lo scudo è pieno."
L["Empty end"] = "Estremo vuoto"
L["The gradient's color where the shield runs out."] = "Il colore della sfumatura dove lo scudo finisce."
L["Left / right"] = "Sinistra / destra"
L["Moves the amount left or right from the icon's middle."] = "Sposta il valore a sinistra o a destra dal centro dell'icona."
L["Down / up"] = "Giù / su"
L["Moves the amount down or up from the icon's middle."] = "Sposta il valore in giù o in su dal centro dell'icona."
L["How big the amount's text is."] = "Quanto è grande il testo del valore."
L["Which buffs get a ring, and the game's timer: the Cooldown Manager page, under Look."] = "Quali effetti benefici hanno un anello, e il timer del gioco: pagina Gestore dei tempi di recupero, sotto Aspetto."
L["Pips in a ring round the icon."] = "Tacche ad anello attorno all'icona."
L["Edge pips"] = "Tacche sul bordo"
L["Square pips along the icon's edge."] = "Tacche quadrate lungo il bordo dell'icona."
L["Row pips"] = "Tacche in fila"
L["A row of square pips under the icon."] = "Una fila di tacche quadrate sotto l'icona."
L["Corner number"] = "Numero nell'angolo"
L["The cooldown's seconds in the icon's corner."] = "I secondi del tempo di recupero nell'angolo dell'icona."
L["Pips:"] = "Tacche:"
L["Four pips: a big step each."] = "Quattro tacche: un bel salto ciascuna."
L["Eight pips."] = "Otto tacche."
L["Twelve pips: small steps."] = "Dodici tacche: piccoli passi."
L["Plain white."] = "Bianco semplice."
L["Click to choose the cooldown's color."] = "Clicca per scegliere il colore del tempo di recupero."
L["Which spells show both: the Cooldown Manager page, Look, Shows."] = "Quali incantesimi mostrano entrambi: pagina Gestore dei tempi di recupero, Aspetto, Visibili."

-- Style/CombatTextPage.lua
L["You may see other people's damage as your own."] = "Potresti vedere i danni degli altri come se fossero tuoi."
L["Each text starts out looking like the one it's under. Changing one only changes that one."] = "Ogni testo all'inizio ha l'aspetto di quello sopra di lui. Cambiarne uno cambia solo quello."
L["Spells"] = "Incantesimi"
L["A look of their own for any of your spells."] = "Un aspetto tutto loro per qualsiasi tuo incantesimo."
L["Ours look the way the Look tab sets them. The game's look as they always do."] = "I nostri seguono la scheda Aspetto. Quelli del gioco restano come sempre."
L["The game's own numbers, the way it normally draws them."] = "I numeri del gioco, come li disegna di solito."
L["Set XP and other floating text to The game's first. While it's on None, the game draws none of its numbers."] = "Prima metti PE e altro testo fluttuante su Del gioco. Finché è su Nessuna, il gioco non disegna nessuno dei suoi numeri."
L["Ours when you're solo. In a group or raid, the game's own, which show every pet hit."] = "I Nostri quando sei da solo. In gruppo o incursione, quelli del gioco, che mostrano ogni colpo del famiglio."
L["In a group, ours only show your pet's spells, since its swings look the same as everyone else's. The game's shows every pet hit in its own look."] = "In gruppo, i nostri mostrano solo gli incantesimi del tuo famiglio, perché i suoi colpi normali sono identici a quelli di tutti gli altri. Del gioco mostra ogni colpo del famiglio col suo aspetto."
L["Hides all the game's floating text, damage numbers included. Log out and back in to apply."] = "Nasconde tutto il testo fluttuante del gioco, numeri dei danni compresi. Esci e rientra per applicarlo."
L["Log out and back in to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "Esci e rientra per applicarlo. Se è nascosto il gioco non disegna nessuno dei suoi numeri, quindi Del gioco è grigio nelle righe qui sopra."
L["Log out and back in to apply: until then the game's floating text stays hidden."] = "Esci e rientra per applicarlo: fino ad allora il testo fluttuante del gioco resta nascosto."
L["None hides all of the game's floating text, damage numbers included. It takes a log out and back in."] = "Nessuna nasconde tutto il testo fluttuante del gioco, numeri dei danni compresi. Bisogna uscire e rientrare."
L["Each row sets many texts at once. You can change any of them afterward in the table below."] = "Ogni riga imposta tanti testi insieme. Poi puoi cambiarne qualsiasi nella tabella qui sotto."
L["Shows only your crits and misses, with plain hits and heals turned off."] = "Mostra solo i tuoi critici e i colpi mancati, senza i colpi e le cure normali."
L["Plain hits and heals are off and crits and misses are on. Switch any of them back in the table."] = "Colpi e cure normali sono disattivati, critici e colpi mancati attivi. Puoi riattivarli nella tabella."
L["Turns off your auto attacks, along with their crits and misses."] = "Disattiva i tuoi attacchi automatici, insieme ai loro critici e colpi mancati."
L["Crits and your casts show in the middle, and the rest move aside."] = "Critici e incantesimi lanciati appaiono al centro, e il resto si sposta di lato."
L["Your pet's hits show smaller than yours."] = "I colpi del tuo famiglio appaiono più piccoli dei tuoi."
L["Your pet's hits show as big as yours."] = "I colpi del tuo famiglio appaiono grandi come i tuoi."
L["Every number is three quarters of the game's size."] = "Ogni numero è grande tre quarti di quelli del gioco."
L["Swings are smaller, and spells and heals get bigger the longer their cast."] = "I colpi normali sono più piccoli, e incantesimi e cure diventano più grandi quanto più lungo è il lancio."
L["Every number stays three quarters as long as the game's."] = "Ogni numero resta tre quarti del tempo di quelli del gioco."
L["Swings stay up for less time, and spells and heals stay longer the longer their cast."] = "I colpi normali restano meno, e incantesimi e cure restano di più quanto più lungo è il lancio."
L["Puts everything on this tab back to its defaults."] = "Riporta tutto in questa scheda ai valori predefiniti."
L["How big it is compared to the game's."] = "Quanto è grande rispetto a quello del gioco."
L["How big its crits are compared to its hits."] = "Quanto sono grandi i suoi critici rispetto ai colpi normali."
L["Adds (Glancing), (Blocked) or (Resisted) after the number. In a fight, the amount is hidden."] = "Aggiunge (Di striscio), (Bloccato) o (Resistito) dopo il numero. In combattimento il valore è nascosto."
L["How far it moves compared to the game's."] = "Quanto si sposta rispetto a quello del gioco."
L["How long it stays compared to the game's."] = "Quanto resta rispetto a quello del gioco."
L["How far into its time on screen it starts to fade."] = "A che punto del suo tempo sullo schermo inizia a dissolversi."
L["Grows big for a moment, then settles, like the game's crits."] = "Si ingrandisce per un attimo, poi torna normale, come i critici del gioco."
L["Shows or hides it. Turning it off hides the texts under it too, except crits, which have their own."] = "Lo mostra o lo nasconde. Disattivarlo nasconde anche i testi sotto di lui, tranne i critici, che hanno il loro."
L["This text's own look, on top of the one above it."] = "L'aspetto di questo testo, in aggiunta a quello sopra di lui."
L["Your own word in place of the game's (%s). Leave it empty to use the game's."] = "Una tua parola al posto di quella del gioco (%s). Lascia vuoto per usare quella del gioco."

-- Style/CombatTextSpells.lua
L["Spells and abilities"] = "Incantesimi e abilità"
L["Same look"] = "Stesso aspetto"
L["Your spells"] = "I tuoi incantesimi"
L["Each spell starts out looking like its school on the Look tab. Change only what you want."] = "Ogni incantesimo all'inizio ha l'aspetto della sua scuola nella scheda Aspetto. Cambia solo quello che vuoi."
L["+ Add a spell"] = "+ Aggiungi un incantesimo"
L["Add a spell"] = "Aggiungi un incantesimo"
L["Lists the spells you've hit with, then the rest of your spellbook."] = "Elenca gli incantesimi con cui hai colpito, poi il resto del tuo libro degli incantesimi."
L["Find a spell"] = "Cerca un incantesimo"
L["Shows only the spells whose name has this in it. Press Enter to add a spell by its name."] = "Mostra solo gli incantesimi che hanno questo nel nome. Premi Invio per aggiungere un incantesimo col suo nome."
L["Every spell on the list."] = "Tutti gli incantesimi dell'elenco."
L["Changed"] = "Modificati"
L["Only spells with a look of their own."] = "Solo gli incantesimi con un aspetto tutto loro."
L["Puts every spell's look back to its school's. The list stays."] = "Riporta l'aspetto di ogni incantesimo a quello della sua scuola. L'elenco resta."
L["Crits"] = "Critici"
L["Ticks"] = "Tick"
L["No spells yet. Click + Add a spell to give one a look of its own."] = "Ancora nessun incantesimo. Clicca su + Aggiungi un incantesimo per dargli un aspetto tutto suo."
L["As its hits"] = "Come i colpi"
L["This spell"] = "Questo incantesimo"
L["Clear this spell"] = "Cancella questo incantesimo"
L["Its crits"] = "I suoi critici"
L["Its crits' color"] = "Colore dei critici"
L["Its ticks"] = "I suoi tick"
L["Its ticks look like its hits."] = "I suoi tick sembrano i suoi colpi."
L["Its ticks are three quarters of its hits' size."] = "I suoi tick sono grandi tre quarti dei suoi colpi."
L["Shows this spell's numbers or not."] = "Mostra o no i numeri di questo incantesimo."
L["Its color. Right-click: its school's again."] = "Il suo colore. Clic destro: di nuovo quello della scuola."
L["How big its numbers are. Right-click: its school's again."] = "Quanto sono grandi i suoi numeri. Clic destro: di nuovo come la scuola."
L["Its crits' color: its color unless set. Right-click: its color again."] = "Il colore dei suoi critici: il suo colore se non impostato. Clic destro: di nuovo il suo colore."
L["Its ticks (a DoT's, a channel's): the same as its hits, or smaller."] = "I suoi tick (di un DoT, di un incanalamento): uguali ai colpi, o più piccoli."
L["More..."] = "Altro..."
L["Every part of its look: its font, place and motion too."] = "Ogni parte del suo aspetto: anche carattere, posizione e movimento."
L["Takes it off the list. Its numbers look like its school's again."] = "Lo toglie dall'elenco. I suoi numeri tornano come quelli della scuola."
L["Same"] = "Uguali"
L["Off on the Look tab"] = "Disattivato nella scheda Aspetto"
L["No spells match."] = "Nessun incantesimo corrisponde."
L["%d spells, %d with a look of their own"] = "%d incantesimi, %d con un aspetto tutto loro"
L["Search your spells"] = "Cerca tra i tuoi incantesimi"
L["Your spells that hit (this character)"] = "I tuoi incantesimi che hanno colpito (questo personaggio)"
L["Other spells in your spellbook"] = "Altri incantesimi del tuo libro"
L["Not seen yet"] = "Non ancora visti"
L["In the list"] = "Nell'elenco"
L["%d hits"] = "%d colpi"
L["No spells found."] = "Nessun incantesimo trovato."

-- Style/InterfaceRecolor.lua
L["Uses General's bar texture for progress bars, and the theme's color for the fold buttons."] = "Usa la texture delle barre di Generale per le barre di avanzamento, e il colore del tema per i pulsanti per comprimere."
L["Uses General's bar texture for its bars, each in its own color."] = "Usa la texture delle barre di Generale per le sue barre, ognuna nel suo colore."
L["Uses General's text font for its names and numbers."] = "Usa il carattere del testo di Generale per i suoi nomi e numeri."
L["Uses General's bar texture for the bars' fill, with each weapon in its own color."] = "Usa la texture delle barre di Generale per il riempimento delle barre, con ogni arma nel suo colore."
L["Uses General's text font for the bars' text."] = "Usa il carattere del testo di Generale per il testo delle barre."
L["Uses General's text font for their numbers."] = "Usa il carattere del testo di Generale per i loro numeri."

-- Style/LetterboxStyle.lua
L["Preview:"] = "Anteprima:"
L["The weather the Preview shows."] = "Il meteo che mostra l'Anteprima."
L["Shows this weather's tint at its heaviest for a few seconds (at 50% while Strength is Off)."] = "Mostra la tinta di questo meteo al massimo per qualche secondo (al 50% quando Intensità è Disattivato)."
L["On the screen"] = "Sullo schermo"
L["Shows it for a few seconds, in CineMode or not (at 50% while it's Off)."] = "La mostra per qualche secondo, in CineMode o no (al 50% quando è Disattivato)."
L["Heavier weather"] = "Meteo più intenso"
L["Medium"] = "Medio"
L["Heavy"] = "Intenso"
L["Makes the game's own rain and snow thicker while its row is on, and puts yours back after."] = "Rende più fitte la pioggia e la neve del gioco finché la sua riga è attiva, e poi rimette le tue impostazioni."
L["Pulls the view distance in as a downpour would, for a few seconds."] = "Riduce la distanza visiva come farebbe un acquazzone, per qualche secondo."
L["The world"] = "Il mondo"
L["Draw the world between the bars"] = "Mostra il mondo tra le bande"
L["Shows the whole view between the bars instead of hiding its top and bottom (it changes only out of fights)."] = "Mostra tutta la visuale tra le bande invece di nasconderne la parte alta e bassa (cambia solo fuori dal combattimento)."
L["Shows the whole time in CineMode, including fights and the Calm Timer after them."] = "Si vede sempre in CineMode, combattimenti compresi e il Timer di calma dopo."
L["When on, the bars look the way this page sets them. When off, they're Cinematic's plain black bars."] = "Se attiva, le bande hanno l'aspetto che imposta questa pagina. Se disattivata, sono le semplici bande nere di Cinematic."
L["Takes the bars out and brings them back in, like at the start and end of a fight."] = "Fa uscire le bande e le fa rientrare, come all'inizio e alla fine di un combattimento."
L["Shapes the space between the bars like a movie screen, on any monitor."] = "Dà allo spazio tra le bande la forma di uno schermo da cinema, su qualsiasi monitor."
L["How tall the top bar is, as a share of the screen's height."] = "Quanto è alta la banda sopra, in proporzione all'altezza dello schermo."
L["Click to link or unlink the two bars. Linked, they're the same height."] = "Clicca per collegare o scollegare le due bande. Collegate, hanno la stessa altezza."
L["How tall the bottom bar is, as a share of the screen's height."] = "Quanto è alta la banda sotto, in proporzione all'altezza dello schermo."
L["How long the bars take to come in or go. Set to 0 to match the UI's fade."] = "Quanto ci mettono le bande a entrare o uscire. Metti 0 per seguire la dissolvenza dell'interfaccia."
L["How the weather tints the scene: a color for each weather, and how fast it comes in and goes."] = "Come il meteo colora la scena: un colore per ogni meteo, e quanto in fretta arriva e se ne va."
L["When on, the weather uses the colors and time set here. When off, Cinematic's own."] = "Se attiva, il meteo usa i colori e i tempi impostati qui. Se disattivata, quelli di Cinematic."
L["Pick this weather's tint. White is no change; darker colors darken the scene more."] = "Scegli la tinta di questo meteo. Bianco non cambia niente; i colori più scuri scuriscono di più la scena."
L["How long the weather's tint takes to come in as it starts, or to go as it clears or you step inside."] = "Quanto ci mette la tinta del meteo ad arrivare quando inizia, o ad andarsene quando smette o entri al chiuso."

-- Style/MinimapStyle.lua
L["Minimap Style"] = "Stile della minimappa"
L["How the minimap looks: its shape, border and ring."] = "L'aspetto della minimappa: forma, bordo e anello."
L["Turns this page's minimap look on or off."] = "Attiva o disattiva l'aspetto della minimappa di questa pagina."
L["Size and shape"] = "Dimensione e forma"
L["How big the minimap is."] = "Quanto è grande la minimappa."
L["Makes the minimap square."] = "Rende quadrata la minimappa."
L["Border size"] = "Spessore del bordo"
L["How thick the border round the square minimap is. 0: no border."] = "Quanto è spesso il bordo attorno alla minimappa quadrata. 0: nessun bordo."
L["Border color:"] = "Colore del bordo:"
L["Theme uses your theme's ring color, or black when it has none."] = "Tema usa il colore dell'anello del tuo tema, o il nero se non ne ha."
L["Zone name and clock inside"] = "Nome della zona e orologio dentro"
L["Puts the zone name at the top of the square minimap and the clock in its corner."] = "Mette il nome della zona in cima alla minimappa quadrata e l'orologio nell'angolo."
L["Zoom buttons"] = "Pulsanti dello zoom"
L["Hides the minimap's zoom buttons."] = "Nasconde i pulsanti dello zoom della minimappa."
L["Hides the zone name bar over the minimap."] = "Nasconde la barra col nome della zona sopra la minimappa."
L["Hides the day and night dial on the minimap's edge."] = "Nasconde il quadrante giorno e notte sul bordo della minimappa."
L["Ring and buttons"] = "Anello e pulsanti"
L["Colors the rings around minimap buttons in your theme's ring color, or the border color when it has none."] = "Colora gli anelli attorno ai pulsanti della minimappa col colore dell'anello del tuo tema, o col colore del bordo se non ne ha."
L["A little shading just inside the ring, so the map looks set into it."] = "Un po' d'ombra appena dentro l'anello, così la mappa sembra incastonata."
L["Zone bar in the theme's look"] = "Barra della zona con l'aspetto del tema"
L["Shade and the zone bar's look come with themes that have a ring color."] = "L'ombra e l'aspetto della barra della zona arrivano coi temi che hanno un colore dell'anello."

-- Style/PersonalStyle.lua
L["When on, the bars look the way this page sets them. When off, they use the game's own look."] = "Se attiva, le barre hanno l'aspetto che imposta questa pagina. Se disattivata, usano l'aspetto del gioco."
L["It fades to a darker shade of its own color."] = "Sfuma verso una tonalità più scura del suo colore."
L["Its width in screen pixels, so the same number gives two bars the same width."] = "La sua larghezza in pixel dello schermo, così lo stesso numero dà a due barre la stessa larghezza."
L["The health bar's width, growing out from its middle."] = "La larghezza della barra della salute, che cresce dal centro."
L["The power bar's width, growing out from its middle."] = "La larghezza della barra della risorsa, che cresce dal centro."
L["The mana bar's width as a percent of the game's power bar, growing out from its middle."] = "La larghezza della barra del mana in percentuale della barra della risorsa del gioco, che cresce dal centro."
L["The health bar's height compared to the game's."] = "L'altezza della barra della salute rispetto a quella del gioco."
L["The power bar's height compared to the game's."] = "L'altezza della barra della risorsa rispetto a quella del gioco."
L["How big your class resource is compared to the game's size."] = "Quanto è grande la risorsa della tua classe rispetto a quella del gioco."
L["The mana bar's height compared to the power bar's."] = "L'altezza della barra del mana rispetto alla barra della risorsa."
L["The bars' border: the game's or one of ours. Custom sets its thickness and color below."] = "Il bordo delle barre: quello del gioco o uno dei nostri. Personalizzata ne imposta spessore e colore qui sotto."

-- Style/PlateCastStyle.lua
L["When on, the cast bars look the way this page sets them. When off, they use the game's own look."] = "Se attiva, le barre di lancio hanno l'aspetto che imposta questa pagina. Se disattivata, usano l'aspetto del gioco."
L["Makes it part of the unit frame, with its fill, border and font, right under its bars."] = "La fa diventare parte del riquadro dell'unità, con riempimento, bordo e carattere, subito sotto le sue barre."
L["Pick the color of an interrupted cast. The game doesn't report this in every fight."] = "Scegli il colore di un lancio interrotto. Il gioco non lo segnala in tutti i combattimenti."
L["How dark it is behind the fill. This only works with a fill of your own; the game's keeps its own."] = "Quanto è scuro dietro il riempimento. Funziona solo con un riempimento tuo; quello del gioco resta com'è."
L["Its width compared to the game's, growing out from its middle. Nameplates only."] = "La sua larghezza rispetto a quella del gioco, che cresce dal centro. Solo barre dei nomi."
L["The cast bar's height compared to the game's."] = "L'altezza della barra di lancio rispetto a quella del gioco."
L["The icon's size compared to the game's."] = "La dimensione dell'icona rispetto a quella del gioco."
L["A dark shadow behind the letters, down and to the right."] = "Un'ombra scura dietro le lettere, in basso a destra."
L["The look every cast bar uses while its row is set to Default."] = "L'aspetto di ogni barra di lancio finché la sua riga è su Predefinito."
L["Default's (Cast Bars)"] = "Di Predefinito (Barre di lancio)"

-- Style/QuestItemStyle.lua
L["When on, the button looks the way this page sets it. When off, it looks like the game's extra ability button."] = "Se attiva, il pulsante ha l'aspetto che imposta questa pagina. Se disattivata, sembra il pulsante dell'abilità extra del gioco."
L["Icons have their own dark border. Zooming in a little cuts it off."] = "Le icone hanno un loro bordo scuro. Un po' di zoom lo taglia via."
L["A black border around its numbers."] = "Un bordo nero attorno ai suoi numeri."

-- Style/QuestTalkStyle.lua
L["When on, the dialogue looks the way this page sets it. When off, it uses the game's parchment."] = "Se attiva, il dialogo ha l'aspetto che imposta questa pagina. Se disattivata, usa la pergamena del gioco."
L["The size of the bubble and the reply list. Their text grows with them."] = "La dimensione del fumetto e dell'elenco delle risposte. Il loro testo cresce con loro."
L["A black border around the letters, for light text with no panel behind it."] = "Un bordo nero attorno alle lettere, per il testo chiaro senza pannello dietro."
L["The bubble's text in a color of your own. The quest card keeps its own color."] = "Il testo del fumetto in un colore tuo. La scheda della missione mantiene il suo colore."

-- Style/RaidStyle.lua
L["When on, the raid frames look the way this page sets them. When off, they use the game's own look."] = "Se attiva, i riquadri d'incursione hanno l'aspetto che imposta questa pagina. Se disattivata, usano l'aspetto del gioco."
L["Uses the color below at full health, shifting to the At half and Empty colors as health drops."] = "Usa il colore qui sotto a salute piena, e passa ai colori A metà e Vuota man mano che la salute cala."
L["Tints the game's background a color of your own, picked below."] = "Colora lo sfondo del gioco con un colore tuo, scelto qui sotto."
L["The name's size compared to the game's."] = "La dimensione del nome rispetto a quella del gioco."
L["The look every group uses while its row is set to Same as the Default row."] = "L'aspetto di ogni gruppo finché la sua riga è su Come la riga Predefinito."

-- Style/RollStyle.lua
L["When on, the window looks the way this page sets it. When off, it uses Roll Vision's usual look."] = "Se attiva, la finestra ha l'aspetto che imposta questa pagina. Se disattivata, usa il solito aspetto di Roll Vision."
L["A dark panel with a thin line around it, in the item's quality color."] = "Un pannello scuro con una linea sottile attorno, nel colore della qualità dell'oggetto."

