L["Taken on one side, gained on the other."] = "Quello che perdi da un lato, quello che ottieni dall'altro."
L["Heals on your left, damage on your right, the rest over you."] = "Cure a sinistra, danni a destra, il resto sopra di te."
L["Sits beside you while the camera is over your shoulder."] = "Sta accanto a te mentre la telecamera è alle tue spalle."
L["Moves it up or down from your spot."] = "Lo sposta in su o in giù dalla tua posizione."
L["Moves it left or right from your spot."] = "Lo sposta a sinistra o a destra dalla tua posizione."
L["How long each text stays."] = "Quanto resta ogni testo."
