L["Puts all your changes to this card type back to the defaults."] = "Riporta ai valori predefiniti tutte le tue modifiche a questo tipo di scheda."
L["No new Zone or Subzone card for this long after one. Set to 0 to show one every time."] = "Nessuna nuova scheda Zona o Sottozona per questo tempo dopo una. Metti 0 per mostrarla ogni volta."
L["The words as you go into a fight against players; leave empty for none."] = "Le parole quando entri in un combattimento contro giocatori; lascia vuoto per nessuna."
L["No card after fights shorter than this. Set to 0 for every fight."] = "Nessuna scheda dopo combattimenti più brevi di così. Metti 0 per tutti i combattimenti."
L["The opening words (on a card, over the zone name)."] = "Le parole d'apertura (su una scheda, sopra il nome della zona)."
L["Its usual card, in its own look (the Style tab)."] = "La sua solita scheda, col suo aspetto (la scheda Stile)."
L["A picture in its own colors: red with a dark outline on a flat black band."] = "Un'immagine coi suoi colori: rosso con un contorno scuro su una fascia nera piatta."
L["Shows the line only this long at the start and end. All the way left (Off) shows it the whole way."] = "Mostra la linea solo per questo tempo all'inizio e alla fine. Tutto a sinistra (Disattivato) la mostra per tutto il tempo."

-- Visions/CombatSoundRules.lua
L["How loud the sounds are, compared to your sound effects volume."] = "Quanto sono forti i suoni, rispetto al volume degli effetti sonori."
L["This sound's volume, compared to the others."] = "Il volume di questo suono, rispetto agli altri."
L["Resets this card's rules to the defaults."] = "Riporta le regole di questa scheda a quelle predefinite."
L["Resets this tab to its default rules: one sound as any other fight starts and one as it ends."] = "Riporta questa scheda alle regole predefinite: un suono all'inizio di ogni altro combattimento e uno alla fine."

-- Visions/DamageVision.lua
L["Shows in every fight, wherever you are, so the other columns don't matter."] = "Appare in ogni combattimento, ovunque tu sia, quindi le altre colonne non contano."
L["Shows how you did on that boss as it dies."] = "Mostra com'è andata su quel boss quando muore."
L["Shows how you did on the whole run once it's done."] = "Mostra com'è andata in tutta la spedizione quando è finita."
L["Shows the recap card with the meter's whole run if you have one, or a made-up one if not (Stop hides it)."] = "Mostra la scheda di riepilogo con tutta la spedizione del misuratore se ne hai una, o una inventata se no (Ferma la nasconde)."
L["Shows your place over it (#2)."] = "Mostra sopra la tua posizione (#2)."
L["A crown pops in as you take #1."] = "Appare una corona quando arrivi al #1."
L["Shows the name of the one you race, in their class's color."] = "Mostra il nome di chi stai sfidando, nel colore della sua classe."
L["Shows your damage (or healing) so far."] = "Mostra i tuoi danni (o cure) fino a ora."
L["Shows each player's name on their row."] = "Mostra il nome di ogni giocatore sulla sua riga."
L["Amber while you're behind, teal once you lead, or two colors of your own."] = "Ambra quando sei indietro, verde acqua quando sei in testa, o due colori tuoi."

-- Visions/EmoteVision.lua
L["Emote Vision test: you'd %s."] = "Prova di Emote Vision: faresti %s."
L["Turn it on and pick which moments show a card, and the emotes on each."] = "Attivalo e scegli quali momenti mostrano una scheda, e le emote di ognuno."
L["Cards that need the other player's nameplate. CineMode keeps it for them."] = "Schede che hanno bisogno della barra del nome dell'altro giocatore. CineMode la tiene per loro."
L["Puts the menu's emotes back to the defaults."] = "Riporta le emote del menu a quelle predefinite."
L["Shows wherever you are, but never in a fight. A card that comes up in a fight waits for it to end."] = "Appare ovunque tu sia, ma mai in combattimento. Una scheda che arriva in combattimento aspetta che finisca."
L["Puts every moment's emotes back to the defaults."] = "Riporta le emote di ogni momento a quelle predefinite."
L["Only buffs from strangers bring up a card, not buffs from your party or raid."] = "Solo gli effetti benefici degli sconosciuti fanno apparire una scheda, non quelli del tuo gruppo o incursione."

-- Page names and lists
L["A Minimap page in the Style hub: make the minimap square with a border in your theme's color, change its size, and hide its zoom buttons, zone bar or day and night dial."] = "Una pagina Minimappa nel gruppo Stile: rendi quadrata la minimappa con un bordo nel colore del tuo tema, cambiane la dimensione, e nascondi i pulsanti dello zoom, la barra della zona o il quadrante giorno e notte."
L["A boss down in a dungeon or raid with your group (each one, not just the last): the emotes go to everyone."] = "Un boss sconfitto in spedizione o incursione col tuo gruppo (ognuno, non solo l'ultimo): le emote vanno a tutti."
L["A boss's name as a title card, as its fight starts or as you first target it or come near: on the screen, in a letterbox bar or low on the left like a film, with its dungeon and which boss it is. Its look has its own tab on Battle Vision's Style page."] = "Il nome di un boss come titolo, quando inizia il combattimento o quando lo prendi di mira o ti avvicini la prima volta: sullo schermo, in una banda nera o in basso a sinistra come in un film, con la spedizione e quale boss è. Il suo aspetto ha una scheda sua nella pagina Stile di Battle Vision."
L["A buff of a minute or more someone else puts on you (Fortitude, Arcane Intellect, a blessing...). Not heals over time."] = "Un effetto benefico di un minuto o più che qualcun altro ti lancia (Robustezza, Intelletto Arcano, una benedizione...). Non le cure nel tempo."
L["A button on the inspect window opens the player's talents, and one on the talents window takes you back."] = "Un pulsante nella finestra d'ispezione apre i talenti del giocatore, e uno nella finestra dei talenti ti riporta indietro."
L["A calculator button on your talents window opens a talent planner that looks just like it, starting from your talents. Plan a build, see the level it needs, then copy it over to your talents window to apply."] = "Un pulsante calcolatrice nella finestra dei talenti apre un pianificatore identico, che parte dai tuoi talenti. Prepara una build, guarda che livello serve, poi copiala nella finestra dei talenti per applicarla."
L["A cue as you go into a fight and come out of it: a word on the screen or in a letterbox bar, a pulse around the edges, an icon, and sounds you pick for each kind of fight, like horns for a raid boss. Its look has a page in the Style hub, with presets and a preview."] = "Un segnale quando entri ed esci da un combattimento: una parola sullo schermo o in una banda nera, un impulso sui bordi, un'icona, e i suoni che scegli per ogni tipo di combattimento, come i corni per un boss d'incursione. Il suo aspetto ha una pagina nel gruppo Stile, con preimpostazioni e anteprima."
L["A grid that shows or hides each part of the nameplates in CineMode: health bar, name, cast bar, buffs, level and more."] = "Una griglia che mostra o nasconde ogni parte delle barre dei nomi in CineMode: barra della salute, nome, barra di lancio, effetti, livello e altro."
L["A mark on your target's nameplate for when no target frame shows who you've got: an arrow, chevron, glow or brackets, colored by how they see you."] = "Un segno sulla barra del nome del bersaglio per quando nessun riquadro del bersaglio ti mostra chi hai preso: una freccia, una V, un bagliore o delle parentesi, colorati in base a come ti vede."
L["A new Retail profile gives WoW Forever retail's look: Cinematic's own Edit Mode layout, with action bars 1 to 3, the micro menu and bags, and the XP bar each coming up on its own. Switch back to Default and your own layout returns."] = "Un nuovo profilo Retail dà a WoW Forever l'aspetto di retail: la disposizione della Modalità Modifica di Cinematic, con le barre delle azioni da 1 a 3, il micromenu e le borse, e la barra dell'esperienza che appaiono ognuna per conto suo. Torna a Predefinito e ritrovi la tua disposizione."
L["A new Spells tab on Combat Text Style gives any of your spells its own color, size and look, its crits and DoT ticks too."] = "Una nuova scheda Incantesimi in Stile del testo di combattimento dà a qualsiasi tuo incantesimo colore, dimensione e aspetto suoi, anche ai critici e ai tick dei DoT."
L["A new Vision for the words that fade in on your screen between fights: what you did last time as you log in (\"Last time: Darkshore · 3 quests done · reached level 24\"), the time of day, a place under attack, and the death banner, each with its own tick and a Test button. Combat Vision is now called Battle Vision."] = "Una nuova Vision per le parole che appaiono sullo schermo tra un combattimento e l'altro: cosa hai fatto l'ultima volta quando entri (\"L'ultima volta: Rivafosca · 3 missioni completate · raggiunto il livello 24\"), l'ora del giorno, un luogo sotto attacco e lo striscione di morte, ognuno con la sua spunta e un pulsante Prova. Combat Vision ora si chiama Battle Vision."
L["A new Wheels page shows every wheel and its icons, with its keybind right there, and lets you pick which wheels sit on the master wheel and in what order."] = "Una nuova pagina Ruote mostra ogni ruota e le sue icone, col suo tasto lì accanto, e ti fa scegliere quali ruote stanno sulla ruota principale e in che ordine."
L["A new page in the Community hub with links to the Discord, YouTube, CurseForge and GitHub, ready to copy."] = "Una nuova pagina nel gruppo Comunità coi link a Discord, YouTube, CurseForge e GitHub, pronti da copiare."
L["A new rule editor"] = "Un nuovo editor delle regole"
L["A place new to you: a zone the first time you're there, a subzone as the game says you discovered it, a dungeon or raid the first time you go in. In place of the Zone or Subzone card."] = "Un luogo nuovo per te: una zona la prima volta che ci sei, una sottozona quando il gioco dice che l'hai scoperta, una spedizione o incursione la prima volta che entri. Al posto della scheda Zona o Sottozona."
L["A track with you above it and your rival below; the gap between you in color."] = "Una pista con te sopra e il tuo rivale sotto; la distanza tra voi a colori."
L["After an update with new features, a line in chat at login says so, with a link to What's new. Turn it off on the Chat page."] = "Dopo un aggiornamento con nuove funzioni, all'accesso una riga in chat te lo dice, con un link a Novità. Si disattiva nella pagina Chat."
L["An over-the-shoulder camera: you sit to one side of the screen and stay there as you zoom. Swap shoulders with a key, turn toward the NPCs you talk to and the enemies you target, and let your cast bar and resources slide along with you."] = "Una telecamera alle spalle: stai su un lato dello schermo e ci resti mentre usi lo zoom. Cambia spalla con un tasto, girati verso i PNG con cui parli e i nemici che prendi di mira, e fai scorrere con te la barra di lancio e le risorse."
L["Arcane stars"] = "Stelle arcane"
L["As a dungeon's or raid's last boss goes down: its name, the time since you came in and how many times you died."] = "Quando cade l'ultimo boss di una spedizione o incursione: il suo nome, il tempo da quando sei entrato e quante volte sei morto."
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal opens around you in your class and spec's color, closing in as the cast fills, then the screen goes black as you're whisked away. It plays alongside the tele camera."] = "Quando usi la Pietra del Ritorno, Richiamo Astrale o un teletrasporto, attorno a te si apre un portale nel colore della tua classe e specializzazione, che si stringe man mano che il lancio si riempie, poi lo schermo diventa nero mentre vieni portato via. Va insieme alla telecamera di teletrasporto."
L["As you come into an inn or a city (not at login, not in a fight): the place's name. The same place at most once every 10 minutes."] = "Quando entri in una locanda o in una città (non all'accesso, non in combattimento): il nome del luogo. Lo stesso luogo al massimo una volta ogni 10 minuti."
L["As you reach a new level (after the fight, if you're in one): the level, the zone and how long it took this session. Max level at the cap."] = "Quando raggiungi un nuovo livello (dopo il combattimento, se ci sei dentro): il livello, la zona e quanto ci hai messo in questa sessione. Livello massimo quando arrivi al tetto."
L["As you turn in a story quest (campaign, important or legendary) or a dungeon, raid or elite one: its title."] = "Quando consegni una missione della storia (campagna, importante o leggendaria) o una di spedizione, incursione o élite: il suo titolo."
L["As your health drops, dark edges creep in around the screen with art themed to your class and talents (blood, frost, fire...), a heartbeat that quickens and a flash on big hits, so you can tell how you're doing at a glance."] = "Quando la salute cala, bordi scuri avanzano attorno allo schermo con una grafica a tema con la tua classe e i tuoi talenti (sangue, gelo, fuoco...), un battito che accelera e un lampo sui colpi forti, così capisci al volo come stai messo."
L["At an NPC"] = "Da un PNG"
L["BigWigs, TomTom, HealBot Continued and Titan Panel get rows of their own and fade with Cinematic. Platynator and Threat Plates nameplates fade in CineMode, and Prat 3.0's chat follows the Chat page."] = "BigWigs, TomTom, HealBot Continued e Titan Panel hanno righe loro e si dissolvono con Cinematic. Le barre dei nomi di Platynator e Threat Plates si dissolvono in CineMode, e la chat di Prat 3.0 segue la pagina Chat."
L["Blood mist"] = "Nebbia di sangue"
L["Camera Modes and Camera Triggers are now one Cameras page: a row for each trigger (an emote, a campfire, going AFK, a flight...) with the camera it starts, its music and CineMode, and where it can start. Copy a row to give a trigger a different camera in other places."] = "Modalità telecamera e Attivatori telecamera ora sono una sola pagina Telecamere: una riga per ogni attivatore (un'emote, un falò, andare AFK, un volo...) con la telecamera che avvia, la sua musica e CineMode, e dove può partire. Copia una riga per dare a un attivatore un'altra telecamera in altri posti."
L["Change any Vitals Vision theme's art, colors, sparks and heartbeat, or make themes of your own from one, and rename or delete them. Reset theme puts one of ours back as it comes."] = "Cambia grafica, colori, scintille e battito di qualsiasi tema di Vitals Vision, o crea temi tuoi partendo da uno, e rinominali o eliminali. Ripristina tema rimette uno dei nostri com'era all'inizio."
L["ClassicUI Forever's action bars, bar art and quest watch now fade with Cinematic, and come back when you hover them."] = "Le barre delle azioni, la grafica delle barre e l'elenco missioni di ClassicUI Forever ora si dissolvono con Cinematic, e tornano quando ci passi sopra col mouse."
L["Click the star beside any settings page's search box to save that page, open at the tab you're on. Your favorites get their own line at the top of Cinematic's list."] = "Clicca la stella accanto alla casella di ricerca di qualsiasi pagina delle impostazioni per salvarla, aperta sulla scheda in cui sei. I tuoi preferiti hanno una riga tutta loro in cima all'elenco di Cinematic."
L["Combat text by spell"] = "Testo di combattimento per incantesimo"
L["Cooldown Manager grid"] = "Griglia del Gestore dei tempi di recupero"
L["Creeping shadow"] = "Ombra strisciante"
L["Ctrl+Click an auction to see it on your character in a small dressing room beside the Auction House, which now stays open. Turn it on in Quality of Life."] = "Ctrl+Clic su un'asta per vederla addosso al personaggio in un piccolo camerino accanto alla Casa d'Aste, che ora resta aperta. Si attiva in Comodità."
L["Dressing room at the Auction House"] = "Camerino alla Casa d'Aste"
L["Earth wisps"] = "Fuochi fatui di terra"
L["ElvUI's frames, Deadly Boss Mods' timer bars and RestedXP's guide window now fade in CineMode: ElvUI's following the Game Frames rows of the frames they replace, RestedXP's with the Quest tracker row."] = "I riquadri di ElvUI, le barre dei timer di Deadly Boss Mods e la finestra della guida di RestedXP ora si dissolvono in CineMode: quelli di ElvUI seguono le righe Riquadri del gioco dei riquadri che sostituiscono, quella di RestedXP la riga Elenco missioni."
L["Embers"] = "Braci"
L["Every camera is now a script of steps (turn, zoom, sway, wait, follow...) on the new Scripts page in the Camera hub. Pick one to see how it moves, change its steps and settings there, or copy it to make a camera of your own."] = "Ogni telecamera ora è uno script di passi (girare, zoom, ondeggiare, attendere, seguire...) nella nuova pagina Script del gruppo Telecamera. Scegline una per vedere come si muove, cambiane passi e impostazioni lì, o copiala per creare una telecamera tua."
L["Every grid now has the same row: Always, then Combat, Target and Location dropdowns, Roles and Edit. Edit turns a row into a rule, for AND, NOT, Cities and more, with a dot showing whether it's on right now. Chat bubbles, tooltips, effects, music and the cameras now say where they show instead of where they hide."] = "Ora ogni griglia ha la stessa riga: Sempre, poi i menu Combattimento, Bersaglio e Posizione, Ruoli e Modifica. Modifica trasforma una riga in una regola, per AND, NOT, Città e altro, con un punto che mostra se è attiva in questo momento. Fumetti della chat, tooltip, effetti, musica e telecamere ora dicono dove si vedono invece di dove si nascondono."
L["Fel wisps"] = "Fuochi fatui vili"
L["FlareUI's unit frames, resource bars, buffs, quest tracker, party and raid frames fade in CineMode, following the Game Frames rows of the frames they replace."] = "I riquadri delle unità, le barre delle risorse, gli effetti, l'elenco missioni e i riquadri di gruppo e incursione di FlareUI si dissolvono in CineMode, seguendo le righe Riquadri del gioco dei riquadri che sostituiscono."
L["Frames Forever's unit frames follow the Game Frames rows of the frames they replace. ShamanPower's totem bar fades with the Totem bar row, and its cooldown bar gets a row of its own."] = "I riquadri delle unità di Frames Forever seguono le righe Riquadri del gioco dei riquadri che sostituiscono. La barra dei totem di ShamanPower si dissolve con la riga Barra dei totem, e la sua barra dei tempi di recupero ha una riga tutta sua."
L["Frost creeps in on the screen's edges in snow, rain runs down the lens, and lightning flashes with thunder in storms. Off to start with: turn each up on the Weather page."] = "Con la neve il gelo avanza sui bordi dello schermo, la pioggia scorre sull'obiettivo e nelle tempeste lampeggiano fulmini coi tuoni. Disattivati all'inizio: alzali uno per uno nella pagina Meteo."
L["Gliding"] = "Planata"
L["Green wisps"] = "Fuochi fatui verdi"
L["Guidelime support"] = "Supporto per Guidelime"
L["Guidelime's guide window, its ongoing steps and its waypoint arrow get a row each, so you can hide the guide and keep the arrow pointing the way."] = "La finestra della guida di Guidelime, i suoi passi in corso e la sua freccia hanno una riga ciascuno, così puoi nascondere la guida e tenere la freccia che ti indica la strada."
L["Hold a key to bring up a wheel of raid markers and put one on your target, or drop a ground marker where you let go. A master wheel opens any of the wheels from one key. Set the keys on the Keybinds page."] = "Tieni premuto un tasto per aprire una ruota di simboli d'incursione e metterne uno sul bersaglio, o lasciare un segnalino a terra dove rilasci. Una ruota principale apre qualsiasi ruota da un solo tasto. Imposta i tasti nella pagina Tasti."
L["Hold a key to bring up a wheel of the visions and turn Heal, Quest, Duel or Roll Vision on or off, even in a fight. It's on the master wheel too, and each vision has a toggle key of its own on the Keybinds page."] = "Tieni premuto un tasto per aprire una ruota delle Vision e attivare o disattivare Heal, Quest, Duel o Roll Vision, anche in combattimento. C'è anche sulla ruota principale, e ogni Vision ha un suo tasto per attivarla nella pagina Tasti."
L["In CineMode the two players in a duel near you get their nameplates, each duel with its own color border and class icons."] = "In CineMode i due giocatori di un duello vicino a te hanno le loro barre dei nomi, ogni duello col suo bordo colorato e le icone della classe."
L["In a group, a window shows each item being rolled on, with everyone's pick and roll and the winner on top, so you needn't read the rolls in chat. Turn it off in the Visions page."] = "In gruppo, una finestra mostra ogni oggetto in palio, con la scelta e il tiro di tutti e il vincitore in cima, così non devi leggere i tiri in chat. Si disattiva nella pagina Vision."
L["Instead of damage meter numbers, see your race with #1 (or your lead over #2) as a bar, a race track or a ladder, plus a recap of how you did after each boss and dungeon."] = "Invece dei numeri del misuratore dei danni, guarda la tua sfida col #1 (o il tuo vantaggio sul #2) come barra, pista o classifica, più un riepilogo di com'è andata dopo ogni boss e spedizione."
L["Interface, Camera and Quality of life hold their pages behind a row of icons, with one search box for all of them."] = "Interfaccia, Telecamera e Comodità tengono le loro pagine dietro una fila di icone, con una sola casella di ricerca per tutte."
L["Jade wisps"] = "Fuochi fatui di giada"
L["Links to the guidebook, troubleshooting and the bug report form, how to send your log with /cine log, and the Profiler for a slow game, together in Community."] = "I link alla guida, alla risoluzione dei problemi e al modulo per segnalare bug, come mandare il tuo log con /cine log, e il Profiler se il gioco va lento, tutti insieme in Comunità."
L["Lore Forever's subtitles, floating player, new page note and pin card get rows of their own and fade with Cinematic. With Custom dialogue frames on, a Play button on the box with the NPC's words plays the quest's narration or stops it."] = "I sottotitoli, il lettore fluttuante, la nota di nuova pagina e la scheda fissata di Lore Forever hanno righe loro e si dissolvono con Cinematic. Con Riquadri di dialogo personalizzati attivo, un pulsante Riproduci sul riquadro con le parole del PNG avvia o ferma la narrazione della missione."
L["Make scenes, like dungeons in combat, and pick what each spell shows in each one, side by side in one grid. Tick several spells to set them at once, or copy one spell's row onto others."] = "Crea scene, come le spedizioni in combattimento, e scegli cosa mostra ogni incantesimo in ognuna, fianco a fianco in una sola griglia. Spunta più incantesimi per impostarli insieme, o copia la riga di un incantesimo sugli altri."
L["Make your own camera scenes on the Scenes page: an emote, a spell, a buff, a place, a moment or a key can start one, and a scene can have several triggers. The built-in ones are grouped by camera and take triggers of yours too. On My Shots, set how a camera sways and zooms, and share either with a friend."] = "Crea le tue scene della telecamera nella pagina Scene: un'emote, un incantesimo, un effetto, un luogo, un momento o un tasto possono avviarne una, e una scena può avere più attivatori. Quelle di base sono raggruppate per telecamera e accettano anche attivatori tuoi. In Le mie inquadrature, scegli come una telecamera ondeggia e zooma, e condividi l'una o l'altra con un amico."
L["Marks and colors for your focus, the unit under the mouse and a target that's attacking you, not just your target, each with its own look, when it shows, and rows for just enemies or friends. Set them on the Style hub's Nameplates page."] = "Segni e colori per il tuo focus, l'unità sotto il mouse e un bersaglio che ti attacca, non solo il tuo bersaglio, ognuno col suo aspetto, quando appare, e righe solo per nemici o amici. Si impostano nella pagina Barre dei nomi del gruppo Stile."
L["Mobs and NPCs you still need for a quest keep their nameplates up, with a golden ! on their plate and your target frame. Optionally, the quest object in front of you glows so it's easy to spot."] = "I mostri e i PNG che ti servono ancora per una missione tengono la loro barra del nome, con un ! dorato sulla barra e sul riquadro del bersaglio. Se vuoi, l'oggetto della missione davanti a te brilla così lo vedi subito."
L["Motes (class and spec)"] = "Granelli (classe e specializzazione)"
L["Motes of light"] = "Granelli di luce"
L["Nameplates have a hub of their own: which show, the new Icons page for class and role icons, and their looks. Each kind of plate can have its own parts, and each Nameplate Style row its own bar, border, name font and level box."] = "Le barre dei nomi hanno un gruppo tutto loro: quali si vedono, la nuova pagina Icone per le icone di classe e ruolo, e il loro aspetto. Ogni tipo di barra può avere le sue parti, e ogni riga di Stile delle barre dei nomi la sua barra, bordo, carattere del nome e riquadro del livello."
L["Names kept up over faded nameplates in CineMode now look like the game's own names over heads: colored by who they are, and smaller further off."] = "I nomi che restano sopra le barre dei nomi dissolte in CineMode ora sembrano i nomi del gioco sopra le teste: colorati in base a chi sono, e più piccoli da lontano."
L["Naowh Forever's top bar now fades in CineMode (a row on the Addon Frames page), and its RestedXP guide window fades with the Quest tracker row."] = "La barra in alto di Naowh Forever ora si dissolve in CineMode (una riga nella pagina Riquadri degli addon), e la sua finestra della guida RestedXP si dissolve con la riga Elenco missioni."
L["Pick HD or SD for Cinematic's settings and windows on the main page: flat and dark, or the game's own look. Auto follows your client, and your Character Models setting on WoW Forever."] = "Scegli HD o SD per le impostazioni e le finestre di Cinematic nella pagina principale: piatte e scure, o con l'aspetto del gioco. Auto segue il tuo client, e su WoW Forever la tua impostazione Modelli dei personaggi."
L["Pick how much Cinematic does, Subtle, Balanced or Cinema, then Customize changes one part at a time: your layout, camera, look, Visions, chat and sound."] = "Scegli quanto fa Cinematic, Discreto, Bilanciato o Cinema, poi Personalizza cambia una parte alla volta: disposizione, telecamera, aspetto, Vision, chat e suoni."
L["Pick which parts of your frame and the target and focus frames show (portrait, name, level, frame art) for you and each kind of unit, to keep just the bars."] = "Scegli quali parti del tuo riquadro e di quelli del bersaglio e del focus si vedono (ritratto, nome, livello, grafica del riquadro) per te e per ogni tipo di unità, per tenere solo le barre."
L["Plague wisps"] = "Fuochi fatui pestilenziali"
L["Pretends you're auto-running: the auto-run camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Fa finta che tu stia correndo in automatico: la telecamera della corsa automatica va per 30 secondi dove ti trovi. Muoverti, o cliccare Ferma, la termina."
L["Pretends you're auto-walking: the RP walk camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Fa finta che tu stia camminando in automatico: la telecamera della passeggiata GdR va per 30 secondi dove ti trovi. Muoverti, o cliccare Ferma, la termina."
L["Rain"] = "Pioggia"
L["Rain, snow and sandstorms have their own page in Atmosphere. Preview each one, and pick its color and how fast it comes in on the Style tab."] = "Pioggia, neve e tempeste di sabbia hanno una pagina tutta loro in Atmosfera. Guarda l'anteprima di ognuno, e scegli il colore e quanto in fretta arriva nella scheda Stile."
L["Runs Chat Cam for 30 seconds with a made-up conversation between two speakers either side of you. Moving, or clicking Stop, ends it."] = "Avvia la Chat Cam per 30 secondi con una conversazione inventata tra due persone ai tuoi lati. Muoverti, o cliccare Ferma, la termina."
L["Runs the quest camera for 30 seconds as if you were talking to a quest giver in front of you. Moving, or clicking Stop, ends it."] = "Avvia la telecamera delle missioni per 30 secondi come se parlassi con un PNG delle missioni davanti a te. Muoverti, o cliccare Ferma, la termina."
L["Sea breeze"] = "Brezza marina"
L["See how much of your computer's time Cinematic takes, as a graph of the last five minutes, and record a while of play to see which parts cost the most. If Cinematic feels slow, Copy report and send it to us."] = "Guarda quanto tempo del tuo computer usa Cinematic, con un grafico degli ultimi cinque minuti, e registra un po' di gioco per vedere quali parti pesano di più. Se Cinematic ti sembra lento, usa Copia rapporto e mandacelo."
L["See your keyboard on screen with what every key does: its spell's icon, cooldown and count, or the command's name. Hold its key to peek, tap it to keep it up, or type /cine keys. Hold Shift, Ctrl or Alt to see those keys."] = "Guarda la tastiera sullo schermo con cosa fa ogni tasto: l'icona del suo incantesimo, il tempo di recupero e il numero, o il nome del comando. Tieni premuto il suo tasto per sbirciare, premilo una volta per tenerla aperta, o scrivi /cine keys. Tieni premuto Maiusc, Ctrl o Alt per vedere quei tasti."
L["Share a wheel of yours as a line of text and import one from a friend, reading every command first. Icons now come from every icon the game has, like the macro window's, and you can add icons of your own to the marker and vision wheels."] = "Condividi una tua ruota come riga di testo e importane una da un amico, leggendo prima ogni comando. Ora le icone si scelgono tra tutte quelle del gioco, come nella finestra delle macro, e puoi aggiungere icone tue alle ruote dei simboli e delle Vision."
L["Shortly after the death camera starts: YOU DIED across the middle of the screen, \"wasted\" or words of your own. Only with the death camera on (the Die row on the Scenes page)."] = "Poco dopo che parte la telecamera di morte: SEI MORTO al centro dello schermo, \"wasted\" o parole tue. Solo con la telecamera di morte attiva (la riga Morire nella pagina Scene)."
L["Shows a pretend card for each moment in turn (close the settings to see it). With someone targeted it's theirs, and its buttons really emote at them; with no one, they only say in chat what they'd do."] = "Mostra una scheda finta per ogni momento, uno dopo l'altro (chiudi le impostazioni per vederla). Se hai qualcuno come bersaglio è la sua, e i pulsanti fanno davvero l'emote verso di lui; senza nessuno, dicono solo in chat cosa farebbero."
L["Six new Vitals Vision themes are built from the game's own full-screen effects, moving and closing in as your health drops: Cosmic void, Hellfire, Radiance, Frostbite, Fel flames and Spellfire. Find them under More themes."] = "Sei nuovi temi di Vitals Vision fatti con gli effetti a schermo intero del gioco, che si muovono e si stringono quando la salute cala: Vuoto cosmico, Fuoco infernale, Radiosità, Congelamento, Fiamme vili e Fuoco arcano. Li trovi in Altri temi."
L["Someone from your guild (not in your group) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Qualcuno della tua gilda (non nel tuo gruppo) compare: con le barre dei nomi amiche attive, appena lo vedi; altrimenti quando ci passi sopra col mouse o lo prendi come bersaglio. Una volta all'ora per persona."
L["Someone near you earns an achievement (a stranger, someone in your group or in your guild)."] = "Qualcuno vicino a te ottiene un'impresa (uno sconosciuto, qualcuno del tuo gruppo o della tua gilda)."
L["Someone you grouped with lately (the game's Recent Allies, not in your group now) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Qualcuno con cui sei stato in gruppo di recente (gli Alleati recenti del gioco, ora non nel tuo gruppo) compare: con le barre dei nomi amiche attive, appena lo vedi; altrimenti quando ci passi sopra col mouse o lo prendi come bersaglio. Una volta all'ora per persona."
L["Souls"] = "Anime"
L["Spanish, German, French, Russian, Portuguese, Italian, Korean and Chinese, with a Language choice on the main page."] = "Spagnolo, tedesco, francese, russo, portoghese, italiano, coreano e cinese, con la scelta Lingua nella pagina principale."
L["Starlight"] = "Luce stellare"
L["Talking to an NPC, their words show in a speech bubble over their head and your replies in a list below, instead of the game's gossip and quest windows. Pick a reply with 1-9, and Space to read on."] = "Quando parli con un PNG, le sue parole appaiono in un fumetto sopra la sua testa e le tue risposte in un elenco sotto, invece delle finestre di dialogo e missione del gioco. Scegli una risposta con 1-9, e Spazio per andare avanti."
L["The Addon Frames page's Find frames tab can look for other addons' frames that nothing fades, say which addon made each and guess which row it should follow. Add them with a click."] = "La scheda Trova riquadri della pagina Riquadri degli addon può cercare i riquadri di altri addon che niente dissolve, dire quale addon ha creato ognuno e indovinare quale riga dovrebbe seguire. Aggiungili con un clic."
L["The Camera hub's General page now shows every camera, built in and yours, as an icon. Click one to open a tab with its script and the scenes that play it, and jump straight to either."] = "La pagina Generale del gruppo Telecamera ora mostra ogni telecamera, di base e tue, come icona. Cliccane una per aprire una scheda col suo script e le scene che la usano, e andare dritto all'uno o alle altre."
L["The Cards page has 13 new moments: level up, places discovered, flight arrivals, inns, achievements, reputation, new mounts and pets, profession ranks, story quests, dungeons cleared, rares, battlegrounds and kill streaks. Every card now belongs to one of four looks, so they match out of the box."] = "La pagina Schede ha 13 nuovi momenti: avanzamento di livello, luoghi scoperti, arrivi in volo, locande, imprese, reputazione, nuove cavalcature e mascotte, gradi di professione, missioni della storia, spedizioni completate, rari, campi di battaglia e serie di uccisioni. Ogni scheda ora appartiene a uno di quattro aspetti, così si abbinano subito."
L["The UI fades and letterbox bars come in between fights. Combat, casting and opening windows bring it back."] = "Tra un combattimento e l'altro l'interfaccia si dissolve e arrivano le bande nere. Combattere, lanciare incantesimi o aprire finestre la riporta."
L["The faded minimap comes up when ore, herbs or treasure show on it, a quest of yours is done, or another icon appears, with a ping on the node if you like."] = "La minimappa dissolta ricompare quando ci sono sopra minerali, erbe o tesori, finisci una missione o appare un'altra icona, con un segnale sul punto se vuoi."
L["The first time you enter a zone like Westfall or Duskwood, its name slams onto the screen in huge white capitals. Comes with the new Headline style."] = "La prima volta che entri in una zona come le Marche Occidentali o Boscotetro, il suo nome piomba sullo schermo in enormi maiuscole bianche. Arriva col nuovo stile Titolone."
L["The game's floating combat text about you (hits, heals, misses, power, auras, Low Health) now has a page of its own on Style: a look for each kind, beside your character, and it can follow the Shoulder Cam."] = "Il testo di combattimento fluttuante del gioco su di te (colpi, cure, colpi mancati, risorse, aure, salute bassa) ora ha una pagina tutta sua in Stile: un aspetto per ogni tipo, accanto al personaggio, e può seguire la Shoulder Cam."
L["The game's own graphics settings one by one, past what its Graphics menu allows: ground clutter, view distance and more."] = "Le impostazioni grafiche del gioco una per una, oltre quello che permette il suo menu Grafica: vegetazione, distanza visiva e altro."
L["The game's windows open in the middle of the screen, can be dragged by their title bar and open where you last dropped them. The backpack too."] = "Le finestre del gioco si aprono al centro dello schermo, si trascinano dalla barra del titolo e si riaprono dove le hai lasciate l'ultima volta. Anche lo zaino."
L["The minimap button glows while a vision is doing something, and its menu lists the visions in use with a link to each one's page."] = "Il pulsante della minimappa brilla mentre una Vision sta facendo qualcosa, e il suo menu elenca le Vision in uso con un link alla pagina di ognuna."
L["The names Cinematic draws on faded nameplates in CineMode have a page of their own: their colors, outline, opacity, size and height, with presets and a preview."] = "I nomi che Cinematic disegna sulle barre dei nomi dissolte in CineMode hanno una pagina tutta loro: colori, contorno, opacità, dimensione e altezza, con preimpostazioni e anteprima."
L["The rule editor is rebuilt: words in categories you can search, suggestions as you type, and a line that shows which parts of your rule are true where you stand."] = "L'editor delle regole è rifatto: parole in categorie che puoi cercare, suggerimenti mentre scrivi, e una riga che mostra quali parti della regola sono vere dove ti trovi."
L["Three new cards in the top bar: how much of a zone you've explored, an achievement with one step left, and an achievement's step done. Each shows at most once every 10 minutes; on in the Cinema profile."] = "Tre nuove schede nella banda in alto: quanto hai esplorato di una zona, un'impresa a cui manca un passo, e un passo di un'impresa completato. Ognuna appare al massimo una volta ogni 10 minuti; attive nel profilo Cinema."
L["Tick Copy chat button on the Quality of life page and a small icon in a chat window's corner opens its lines, ready to select and copy with Ctrl+C."] = "Spunta Pulsante Copia chat nella pagina Comodità e una piccola icona nell'angolo di una finestra della chat apre le sue righe, pronte da selezionare e copiare con Ctrl+C."
L["Tick Show speech from behind you on the Chat page and says and yells from people behind you or out of view show as bubbles low on the screen, rising up from below, instead of bringing up chat."] = "Spunta Mostra le parole dette alle tue spalle nella pagina Chat e quello che dice o urla chi sta dietro di te o fuori vista appare in fumetti in basso sullo schermo, che salgono dal fondo, invece di aprire la chat."
L["Type /cine find and a few words, or search in the settings, to get a list of every matching option; click one to go straight to it."] = "Scrivi /cine find e qualche parola, o cerca nelle impostazioni, per avere l'elenco di tutte le opzioni che corrispondono; cliccane una per andarci dritto."
L["Type /cine why, or pick it from the minimap button's menu, then click any frame to see why it's showing or hidden right now and which settings say so. It works on other addons' frames, Cinematic's own (like quest talk), and the last tooltip too. The Why Is It Showing? page in Community lists every row of frames at once."] = "Scrivi /cine why, o sceglilo dal menu del pulsante della minimappa, poi clicca un riquadro qualsiasi per vedere perché adesso è visibile o nascosto e quali impostazioni lo decidono. Funziona sui riquadri di altri addon, su quelli di Cinematic (come i dialoghi delle missioni), e anche sull'ultimo tooltip. La pagina Perché è visibile? in Comunità elenca tutte le righe dei riquadri insieme."
L["Type part of a frame's name, or of the addon that made it, to find frames to fade. Hover a match to see it marked on screen, then click it to fade it."] = "Scrivi parte del nome di un riquadro, o dell'addon che l'ha creato, per trovare riquadri da dissolvere. Passa sopra un risultato per vederlo segnato sullo schermo, poi cliccalo per dissolverlo."
L["Valhalla"] = "Valhalla"
L["Venom wisps"] = "Fuochi fatui velenosi"
L["Vitals Vision's themes now have spiral arms turning over the screen as your health drops, quicker the weaker you are. Set them on the Style page's new Swirl tab, or try the swirl themes under More themes: Vortex, Abyss and Dungeon portal."] = "I temi di Vitals Vision ora hanno bracci a spirale che girano sullo schermo quando la salute cala, più veloci quanto più sei debole. Impostali nella nuova scheda Vortice della pagina Stile, o prova i temi a vortice in Altri temi: Vortice, Abisso e Portale della spedizione."
L["Weather on the screen"] = "Meteo sullo schermo"
L["Weather page"] = "Pagina Meteo"
L["Wheels of your own, up to 8: each icon on one runs a command when you pick it, such as /rw Pull in 10 or /readycheck (anything a macro can do, a line each), in a fight too. Give a wheel its own key here, or put it on the master wheel. They're the same for all your characters."] = "Ruote tue, fino a 8: ogni icona su una ruota esegue un comando quando la scegli, come /rw Pull in 10 o /readycheck (tutto quello che può fare una macro, una riga ciascuno), anche in combattimento. Dai a una ruota il suo tasto qui, o mettila sulla ruota principale. Sono uguali per tutti i tuoi personaggi."
L["When someone buffs you, raises you, emotes at you, summons you or trades with you, or your group kills a boss or levels up, a small card shows who it was, with emotes to answer in one click. Pick each moment's emotes (voice ones too) and one of six card styles."] = "Quando qualcuno ti lancia un effetto benefico, ti resuscita, ti fa un'emote, ti evoca o commercia con te, o il tuo gruppo uccide un boss o sale di livello, una piccola scheda mostra chi è stato, con emote per rispondere in un clic. Scegli le emote di ogni momento (anche quelle vocali) e uno di sei stili di scheda."
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), with your faction's city bell. The same place at most once every 90 seconds."] = "Quando il canale DifesaLocale dice che un luogo è sotto attacco (\"Dun Algaz è sotto attacco!\"), con la campana della città della tua fazione. Lo stesso luogo al massimo una volta ogni 90 secondi."
L["When the time of day changes during play (not in combat), its name with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "Quando cambia l'ora del giorno mentre giochi (non in combattimento), il suo nome con un suono adatto: un gallo all'alba, un cavallo al mattino, la campana della tua fazione a mezzogiorno, le rane la sera, un gufo al crepuscolo e un lupo di notte."
L["Wisps"] = "Fuochi fatui"
L["Wisps (class and spec)"] = "Fuochi fatui (classe e specializzazione)"
L["You and a stranger (not in your group or guild) target each other for 10 seconds straight. Once you've looked away, it can happen again."] = "Tu e uno sconosciuto (non nel tuo gruppo o gilda) vi prendete di mira a vicenda per 10 secondi di fila. Quando avrai distolto lo sguardo, potrà succedere di nuovo."
L["Your character lies down as if dead and the death camera runs for 30 seconds. Moving, or clicking Stop, ends it."] = "Il tuo personaggio si sdraia come se fosse morto e la telecamera di morte va per 30 secondi. Muoverti, o cliccare Ferma, la termina."
L["Your player frame, pet frame and resource display have a page of their own: kept up while you recover or run low on mana, and held back at the start of a fight until your power changes."] = "Il riquadro del giocatore, quello del famiglio e la risorsa hanno una pagina tutta loro: restano visibili mentre recuperi o sei a corto di mana, e all'inizio di un combattimento aspettano finché la risorsa non cambia."
L["\"Dun Algaz is under attack!\" shows in red where the zone name appears, with your faction's city bell."] = "\"Dun Algaz è sotto attacco!\" appare in rosso dove compare il nome della zona, con la campana della città della tua fazione."
